 for(const d of selected){const hub=d.port??gate,first=logisticsPath(source,hub),last=logisticsPath(hub,gate);if(!first.length||!last.length)continue;const path=first.concat(last.slice(1)),roadDays=n=>n>1?Math.ceil((n-1)/(24*quality)):0,pickup=roadDays(first.length),gateway=roadDays(last.length),wait=logisticsQueue(d.id)/d.capacity,price=regionalMarketQuote(m,good,direction==='import'?'imports':'exports'),freight=d.fee+(path.length-1)*.003+m.days*.015;options.push({m,path,price,freight,days:pickup+gateway+m.days+2+Math.ceil(wait),capacity:regionalCapacity(m,good,direction),depot:d.id,depotIndex:first.length-1,pickupDays:pickup,gatewayDays:gateway,handlingFee:d.fee,queueDays:wait,score:freight+wait*price*.012});}
