function logisticsRemember(o,status){const s=ensureRegionalTrade();s.recent.unshift({...o,status,arrived:G.day});if(s.recent.length>36)s.recent.length=36;}
function estateReceipt(f,amount,owner){let left=amount;for(const l of G.loans||[]){if(left<=0)break;if(l.ownerType!=='firm'||l.ownerId!==f.id||l.status!=='default'||l.balance<=0)continue;const paid=Math.min(left,l.balance);l.balance-=paid;l.paid+=paid;left-=paid;const bank=l.bankId>=0?G.banks[l.bankId]:null;if(bank&&!bank.closed){bank.cash+=paid;bank.recoveries=(bank.recoveries||0)+paid}else G.region+=paid;}const household=G.households[owner];if(household?.people.length)household.cash+=left;else G.region+=left;}
