// SOURCE: 28-urban-rehousing.js
// Replacement housing is actual municipal property, commissioned before clearing
// tenants' homes. No household is spawned to occupy this reserved dwelling.
function urbanRehousingQuote(){
 const reserved=G.buildings.filter(b=>b.relocationReserve).length+(G.projects||[]).filter(p=>p.municipalRehousing).length;
 if(reserved>=8)return {ok:false,reason:'Eight replacement homes are already reserved or under construction. Use the existing reserve before commissioning more.'};
 const places=buildableCandidates('housing').filter(p=>canPlace(p.x,p.y,true,'home')).sort((a,b)=>urbanSiteSuitability(b.x,b.y,'home')-urbanSiteSuitability(a.x,a.y,'home')||a.x-b.x||a.y-b.y);
 if(!places.length)return {ok:false,reason:'Connect and zone a vacant residential lot before commissioning replacement housing.'};
 const place=places[0];return {ok:true,x:place.x,y:place.y,cost:buildCost.home,days:24,reason:'Commission a vacant municipal home with road access. It remains reserved for actual displaced residents, rather than creating a new household.'};
}
function commissionUrbanRehousing(quote){
 const reserved=G.buildings.filter(b=>b.relocationReserve).length+(G.projects||[]).filter(p=>p.municipalRehousing).length;
 if(reserved>=8||!quote||quote.cost!==buildCost.home||!Number.isInteger(quote.x)||!Number.isInteger(quote.y)||!canPlace(quote.x,quote.y,true,'home')||G.treasury<buildCost.home)return {ok:false,reason:'The housing site or budget changed. Review the current quote.'};
 const q={x:quote.x,y:quote.y,cost:buildCost.home,days:24};
 const site=startDevelopmentProject('home',q,48000,q.days,{value:48000,municipalRehousing:true});if(!site)return {ok:false,reason:'The quoted site is no longer vacant.'};
 G.treasury-=q.cost;G.region+=q.cost;G.cumulative.spending+=q.cost;G.cumulative.rehousingCapital=(G.cumulative.rehousingCapital||0)+q.cost;
 book('Municipal housing capital','Regional construction contract',q.cost,'Vacant replacement dwelling',site.id);story('A municipal replacement home is under construction. Its tenancy is reserved for people displaced by a later paid land assembly.','neutral',site.id);save();dirty=true;return {ok:true,reason:'Replacement housing commissioned; existing residents retain their homes during construction.',building:site.id};
}
function urbanHousingRent(h,home,base){return home?.municipalRehousing?Math.min(base,Math.max(0,((h.income||0)-(h.tax||0))*.25)):base;}
function urbanMunicipalHousingDay(){
 for(const b of G.buildings){if(!b.municipalRehousing||b.kind!=='home')continue;
  const cost=Math.min(Math.max(0,G.treasury),1);G.treasury-=cost;G.region+=cost;G.cumulative.spending+=cost;G.cumulative.housingMaintenance=(G.cumulative.housingMaintenance||0)+cost;b.condition=clamp(b.condition+(cost>=1?.025:-.04),0,100);
 }
}
function validateUrbanRehousing(data){
 return (data.projects||[]).every(p=>p.municipalRehousing==null||p.municipalRehousing===true&&p.kind==='home'&&p.value===48000&&!p.privateService&&!p.retailCentre)&&data.buildings.every(b=>{
  if(b.municipalRehousing==null&&b.relocationReserve==null)return true;
  return b.kind==='home'&&b.municipalRehousing===true&&typeof b.relocationReserve==='boolean'&&b.owner===-1&&b.title?.kind==='municipal'&&(!b.relocationReserve||!data.households.some(h=>h.home===b.id&&h.people.length));
 });
}

function urbanRelocationFields(x,y,count){
 const footprint=new Set(footprintFor(x,y,'farm')),plots=[];
 for(let radius=1;radius<=8&&plots.length<count;radius++)for(let dy=-radius;dy<=radius;dy++)for(let dx=-radius;dx<=radius;dx++){
  if(Math.abs(dx)+Math.abs(dy)!==radius||plots.length>=count)continue;const px=x+dx,py=y+dy,id=roadId(px,py);
  if(px<3||py<3||px>=T-3||py>=T-3||!charterOwns(px,py)||footprint.has(id)||G.tiles[id]!==0||G.landUse?.[id]||buildingAt(px,py)||!urbanDescriptor(px,py).agricultural||urbanPlacementReason(px,py,'farm'))continue;
  plots.push({id,x:px,y:py});
 }return plots;
}

function urbanRelocationAffordable(h,dest,origin){
 if(dest.municipalRehousing||dest.owner===h.id)return true;
 const base=h.people.length*(3.1+G.policy.zoningRestriction*.035)*(G.housingMarket?.rentIndex||1)*urbanRentMultiplier(dest);
 const wages=h.people.reduce((n,id)=>{const p=G.people[id];if(!p||p.deceased||p.movedAway)return n;if(p.age>70)return n+(G.policy.pensionDaily||0);const f=p.job>=0&&G.firms[p.job];return n+(f&&!f.closed&&!p.commuteBlocked?Math.max(G.policy.minWage,f.wage)*(1-G.policy.incomeTax/100):0);},0);
 const net=Math.max(0,(h.income||0)-(h.tax||0),wages),ownerPremium=urbanTitleAccount(origin)===h?Math.max(0,origin.value*1.1):0;
 const reserve=Math.max(0,householdLiquidity(h)+ownerPremium+2000-h.people.length*200);
 return base<=net*.35+reserve/720;
}

// SOURCE: 29-retail-labour.js
// Shopping-centre labour bids use the same identities, commute limits and
// public-role reservations as actual employment. A forecast never hires people.
function urbanRetailLabour(site,offered=null){
 const net=graph(),port=net.portals.get(site.id)??roadOffsets.map(([dx,dy])=>roadId(site.x+dx,site.y+dy)).find(id=>net.parts[id]===net.mainPart),distances=privateServiceDistances(port),bids=[];
 if(port==null)return bids;
 for(const p of G.people){
  if(p.deceased||p.movedAway||p.age<16||p.age>70||p.publicWork||p.publicRole||p.previousPublicRole||(p.searchAfter||0)>G.day)continue;
  const home=readBuild(G.households[p.hh]?.home),distance=home?distances.get(net.portals.get(home.id))??Infinity:Infinity;if(distance>40)continue;
  const old=p.job>=0?G.firms[p.job]:null;if(old?.privateService||old&&!old.closed&&G.day-(p.privateJobChange||-90)<60)continue;
  const wage=old&&!old.closed?Math.max(G.policy.minWage,workerIncome(old)*1.121):Math.max(G.policy.minWage,28);
  if(offered!=null&&wage>offered+1e-7)continue;
  bids.push({person:p.id,wage,distance});
 }
 return bids.sort((a,b)=>a.wage-b.wage||a.distance-b.distance||a.person-b.person);
}
function urbanRetailPlan(site,customers){
 const units=customers*1.6,staff=clamp(Math.ceil(units/65),2,8),bids=urbanRetailLabour(site);if(bids.length<staff)return null;
 const wage=Math.ceil(bids[staff-1].wage*100)/100,price=G.market?.baseFoodPrice||5.2,cost=marketPrice('food')*1.12,margin=price-cost;
 const rates=220000*(G.policy.commercialRate||0)/100/360,overhead=2+staff*(.6+G.policy.businessRegulation*.035),profit=units*margin-staff*wage-overhead-rates,net=profit*(1-G.policy.profitTax/100);
 return {staff,wage,customers,units,price,cost,profit,net};
}
function recruitUrbanRetailStaff(only=null){
 for(const f of only?[only]:G.firms.filter(f=>f.retailCentre&&!f.closed)){
  if(!f.retailCentre||f.closed||f.workers.length>=f.jobs||f.cash<workerIncome(f)*Math.max(1,f.jobs)*20)continue;const site=readBuild(f.building);if(!site)continue;
  // A vacant operator may revise a funded wage offer after a monthly review.
  // This uses actual reachable retail demand, costs and current labour bids.
  if(!f.workers.length&&G.day-(f.retailHiringReview||0)>=30){
   const bids=urbanRetailLabour(site),bid=bids[0],units=Math.max(1,reachableRetailDemand(f)),margin=f.price-(f.unitCost?.food||marketPrice('food'));
   if(bid&&units*margin-bid.wage-10>0&&f.cash>bid.wage*90){f.wage=Math.max(f.wage,Math.ceil(bid.wage*100)/100);f.retailHiringReview=G.day;}
  }
  for(const bid of urbanRetailLabour(site,workerIncome(f))){if(f.workers.length>=f.jobs)break;const p=G.people[bid.person];if(p.job===f.id)continue;const old=p.job>=0?G.firms[p.job]:null;
   if(old)old.workers=old.workers.filter(id=>id!==p.id);p.job=f.id;p.privateJobChange=G.day;p.commuteBlocked=false;p.commuteBlockedDays=0;f.workers.push(p.id);
  }
 }
}
function validateUrbanRetailLabour(data){
 const number=(n,lo,hi)=>Number.isFinite(n)&&n>=lo&&n<=hi;
 return (data.projects||[]).every(p=>p.retailStaff==null&&p.retailWage==null||p.retailCentre===true&&Number.isInteger(p.retailStaff)&&number(p.retailStaff,2,8)&&number(p.retailWage,10,120))&&data.firms.every(f=>f.retailHiringReview==null||f.retailCentre===true&&Number.isInteger(f.retailHiringReview)&&f.retailHiringReview>=0&&f.retailHiringReview<=data.day);
}

// SOURCE: 30-brownfields.js
// A finite industrial-ground preparation model, not simulated chemical exposure.
// Recorded enterprise operating age establishes previous use; no greenfield is labelled.
const BROWNFIELD_RECORD_LIMIT=3000;
const BROWNFIELD_KINDS=['factory','quarry','sawmill'];
let brownfieldPermit=null;
function brownfieldSites(){return G.brownfields||[];}
function brownfieldDescriptor(s){return {id:s.id,x:s.x,y:s.y,footprint:s.tiles.slice(),formerName:s.name,formerKind:s.kind,formerJobs:s.formerJobs,industrialAgeDays:s.industrialAgeDays,status:s.status,remaining:s.remaining,newBuilding:s.newBuilding??null};}
function brownfieldQuote(id){if(brownfieldSites().length>=BROWNFIELD_RECORD_LIMIT)return {ok:false,reason:'The renewal ledger has reached 3,000 retained sites. Existing projects and provenance are preserved. Withdraw an unacquired survey before recording another; no payment was taken.'};const b=readBuild(id),f=b&&G.firms[b.firm];if(!b||!f||f.demolished||!BROWNFIELD_KINDS.includes(b.kind)||brownfieldSites().some(s=>s.id===id))return {ok:false,reason:'Choose industrial premises; working enterprises require full compensation and worker severance before renewal.'};let clearance;brownfieldPermit=id;try{clearance=urbanClearanceQuote(b.x,b.y);}finally{brownfieldPermit=null;}if(!clearance.ok)return clearance;const days=Math.max(0,Math.floor((f.age||0)-Math.max(0,G.day-(f.closedDay||G.day)))),tiles=footprintOf(b).slice();return {ok:true,id,x:b.x,y:b.y,name:f.name,kind:b.kind,wasClosed:!!f.closed,formerWorkers:f.workers.length,formerJobs:Math.max(0,Math.floor(f.jobs||0)),industrialAgeDays:days,tiles,assessment:300,remediation:1500+tiles.length*750+Math.min(3600,days*8),days:20+Math.min(40,Math.floor(days/30)),clearance:clearance.total,severance:clearance.severance||0,compensation:clearance.compensation||0};}
function brownfieldAssess(id){const q=brownfieldQuote(id);if(!q.ok||G.treasury<q.assessment)return {ok:false,reason:q.reason||'Assessment requires $300 of municipal cash.'};G.treasury-=q.assessment;G.region+=q.assessment;G.cumulative.spending+=q.assessment;const s={...q,status:'assessed',remaining:q.days,assessedDay:G.day};delete s.ok;(G.brownfields||(G.brownfields=[])).push(s);save();return {ok:true,reason:'Assessment recorded. Existing workers, operations and property rights remain unchanged until separately approved acquisition.'};}
function brownfieldAcquire(id,quotedTotal=null){const s=brownfieldSites().find(s=>s.id===id);if(!s||s.status!=='assessed')return {ok:false,reason:'Assess the industrial premises first.'};const b=readBuild(id);if(!b||!G.firms[b.firm]||(s.wasClosed!==false&&!G.firms[b.firm].closed))return {ok:false,reason:'The enterprise reopened or the premises changed.'};brownfieldPermit=id;try{const q=urbanClearanceQuote(s.x,s.y);if(!q.ok)return q;if(quotedTotal!=null&&q.total!==quotedTotal)return {ok:false,reason:'The acquisition price changed; review the current quote.'};const r=urbanClearance(s.x,s.y,q.total);if(!r.ok)return r;s.status='acquired';s.acquiredDay=G.day;s.clearance=q.total;save();return {ok:true,reason:'Recorded owner compensated. Municipal site is held for funded ground preparation.'};}finally{brownfieldPermit=null;}}
function brownfieldFund(id){const s=brownfieldSites().find(s=>s.id===id);if(!s||s.status!=='acquired'||G.treasury<s.remediation)return {ok:false,reason:'Acquire the site and provide the full ground-work contract price.'};G.treasury-=s.remediation;G.region+=s.remediation;G.cumulative.spending+=s.remediation;s.status='remediating';s.startedDay=G.day;s.lastWorkDay=G.day;save();return {ok:true,reason:'Regional ground-work contract paid. Work progresses only with road access; no household or job is created.'};}
function brownfieldDay(){for(const s of brownfieldSites()){if(s.status!=='remediating'||s.lastWorkDay===G.day)continue;s.lastWorkDay=G.day;if(!nearRoad(s.x,s.y)||!G.policy.imports)continue;s.remaining=Math.max(0,s.remaining-1);if(!s.remaining){s.status='ready';s.readyDay=G.day;story(s.name+' ground preparation finished. The municipality can now fund a permitted new use.','good');}}}
function brownfieldReuse(id,kind){const s=brownfieldSites().find(s=>s.id===id);if(!s||s.status!=='ready'||!['home','grocer','park'].includes(kind))return {ok:false,reason:'Finish ground preparation before selecting housing, commerce or a park.'};brownfieldPermit=id;try{if(!canPlace(s.x,s.y,true,kind)||G.treasury<buildCost[kind])return {ok:false,reason:'The new use needs its own capital, current planning permission and road access.'};const before=G.nextId;construct(kind,s.x,s.y,true);const b=buildingAt(s.x,s.y);if(!b||b.id<before)return {ok:false,reason:'The enterprise or construction funding was unavailable.'};s.status='reused';s.newBuilding=b.id;s.reusedDay=G.day;s.newKind=kind;b.brownfieldOrigin=id;save();return {ok:true,reason:s.name+' renewed as '+types[kind].n+'. Existing neighbouring industry still affects local suitability.'};}finally{brownfieldPermit=null;}}
function brownfieldPlacementReason(x,y){const s=brownfieldSites().find(s=>['acquired','remediating','ready'].includes(s.status)&&s.tiles.includes(roadId(x,y)));return s&&brownfieldPermit!==s.id?'Municipal brownfield reserve: finish funded preparation and choose its new use in Public Works.':'';}
