 const jobVacancy=Math.max(0,jobs-employed);
 const homes=G.buildings.reduce((n,b)=>n+(b.kind==='home'?1:b.kind==='apartment'?4:b.kind==='tower'?9:0),0)+(G.projects||[]).filter(p=>p.kind==='home').length;
