$('zoomIn').onclick=()=>{cam.zoom=clamp(cam.zoom*1.22,.025,1.7);dirty=true};$('zoomOut').onclick=()=>{cam.zoom=clamp(cam.zoom/1.22,.025,1.7);dirty=true};$('center').onclick=()=>{if(overlay==='charter'){overlay='none';parcelFocus=null;}centerTownCamera();};$('overlayToggle').onclick=()=>{overlay=overlay==='none'?'roads':overlay==='roads'?'metro':overlay==='metro'?'hardship':overlay==='hardship'?'crime':overlay==='crime'?'business':'none';dirty=true;toast('Map overlay: '+overlay)};
 $('pause').onclick=()=>{paused=!paused;fit();updateHeader();if(paused){draw();save()}};const SPEED_PRESETS=[1,2,4,8,16,32,64];
 $('speed').onclick=()=>{const index=SPEED_PRESETS.indexOf(speed);speed=SPEED_PRESETS[(index+1)%SPEED_PRESETS.length];acc=0;sampleDays=0;sampleSeconds=0;perfStats.effective=0;G.speed=speed;fit();updateHeader()};
 $('speedRange').addEventListener('input',e=>{speed=SPEED_PRESETS[+e.target.value]||1;acc=0;sampleDays=0;sampleSeconds=0;perfStats.effective=0;if(G)G.speed=speed;fit();updateHeader();});
$('speedRange').addEventListener('change',()=>{if(G)save();});
function start(newVillage){if(newVillage){seed(Number($('townSeed')?.value)||42)}else if(!load())seed();centerTownCamera();invalidateRoads();buildMode='';selected=null;overlay='none';paused=false;speed=SPEED_PRESETS.includes(G.speed)?G.speed:1;acc=0;fit();$('welcome').style.display='none';dirty=true;staticDirty=true;updateHeader();openPanel('overview');}
$('newTown').onclick=()=>{start(true);refreshAmbience()};$('continue').onclick=()=>{start(false);refreshAmbience()};
try{if(localStorage.getItem('townledger-v6')||localStorage.getItem('townledger-v6-backup')||localStorage.getItem('townledger-village-founder-3')||localStorage.getItem('townledger-village-civic-2'))$('continue').style.display='block'}catch(e){}
window.addEventListener('resize',fit);fit();
let last=performance.now(),acc=0,lastMapDraw=0,lastHeader=0,lastPanel=0,lastAutosave=performance.now(),speedSample=0,sampleDays=0,sampleSeconds=0;
function frame(now){
 const raw=Math.max(0,(now-last)/1000);last=now;
 if(G&&!paused&&!hostSuspended&&!pendingEvent&&!document.hidden){
  // Admit requested wall time, then do a bounded amount of real simulation work.
  // A bounded queue avoids a multi-minute catchup after an interrupted phone frame.
  const dt=Math.min(raw,.25);acc=Math.min(acc+dt*speed,1.65*8);
  const budget=speed>=16?10:6,end=performance.now()+budget;let completed=0;
  while(acc>=1.65&&(!completed||performance.now()<end)&&!pendingEvent){const t=performance.now();tick();perfStats.ticks.push(performance.now()-t);if(perfStats.ticks.length>180)perfStats.ticks.shift();acc-=1.65;completed++;}
  perfStats.days+=completed;perfStats.elapsed+=dt;perfStats.backlog=acc/1.65;
  sampleDays+=completed;sampleSeconds+=raw;
  if(sampleSeconds>=1){perfStats.effective=sampleDays*1.65/sampleSeconds;sampleDays=0;sampleSeconds=0;}
  if(!gameOptions.reducedMotion){frameClock+=dt;if(gameOptions.traffic)trafficUpdate(dt);}dirty=true;
 }else{sampleDays=0;sampleSeconds=0;if(document.hidden)acc=0;}
 // Native activity transitions can suspend a still-visible WebView. Park all
 // recurring presentation/save work until resume; suspend already saved once.
 if(G&&!document.hidden&&!hostSuspended){
  if(now-lastHeader>=250){updateHeader();lastHeader=now;}
  if(active&&!paused&&now-lastPanel>=1500&&!['policies','citizens','settings','construction'].includes(active)&&!$('panelBody').contains(document.activeElement)){renderPanel(active);lastPanel=now;}
  if(!paused&&now-lastAutosave>=gameOptions.autoSave*1000){save();lastAutosave=now;}
  const fps=speed>=32?Math.min(20,gameOptions.fps):gameOptions.fps;
  if(dirty&&now-lastMapDraw>=1000/fps){const t=performance.now();draw();perfStats.frames.push(performance.now()-t);if(perfStats.frames.length>600)perfStats.frames.shift();lastMapDraw=now;}
 }
 requestAnimationFrame(frame);
}requestAnimationFrame(frame);
window.addEventListener('beforeunload',()=>save());document.addEventListener('visibilitychange',()=>{last=performance.now();acc=0;if(document.hidden){save();stopGameAudio()}else refreshAmbience()});
window.addEventListener('error',e=>{console.error(e.error||e.message);toast('Runtime issue: '+(e.message||'Unknown'))});

// SOURCE: 71-transit-office.js
// Public Works network office; map picks only draft a route. Capital is spent after quote review.
let transitDraft=null;
function cancelTransitDraft(){transitDraft=null;}
function startTransitDraft(mode,editing=-1){
 const routes=ensureTransit().routes,old=routes.find(r=>r.id===editing),depots=G.buildings.filter(b=>b.kind==='transit_depot');if(!depots.length){toast('Build a transit depot beside an owned street first.');return false;}
 transitDraft={town:G,mode:old?.mode||mode,depot:old?.depot||depots[0].id,stops:old?old.stops.slice():[],level:old?.level||1,editing,quote:null};buildMode='transit_route';overlay='transit';dirty=true;openPanel('construction');return true;
}
function transitMapTap(x,y){
 if(buildMode!=='transit_route'||!transitDraft)return false;if(transitDraft.town!==G){closeBuildTool();return true;}
 const draft=transitDraft,id=draft.mode==='bus'?roadId(x,y):buildingAt(x,y)?.id;
 if(draft.mode==='bus'?!transitOwnedRoad(id):readBuild(id)?.kind!=='elevated_station'){toast(draft.mode==='bus'?'Tap an owned road tile for a bus stop.':'Tap an elevated station. Build stations on vacant roadside plots first.');return true;}
 if(draft.stops.includes(id)){toast('This stop is already on the route. Use Undo to remove the latest stop.');return true;}if(draft.stops.length>=16){toast('Sixteen stops per route. Create a connecting route for another corridor.');return true;}
 draft.stops.push(id);draft.quote=null;dirty=true;transitDraftHint();toast('Stop '+draft.stops.length+' added. Open Public Works to review, or continue tapping stops.');return true;
}
function transitDraftHint(){if(!transitDraft)return;$('placementHint').style.display='block';$('placementHint').textContent=TRANSIT_MODES[transitDraft.mode].name.toUpperCase()+' ROUTE · '+transitDraft.stops.length+' STOPS · TAP '+(transitDraft.mode==='bus'?'STREETS':'STATIONS')+' · PUBLIC WORKS TO REVIEW';$('hint').textContent='DRAG TO PAN · TAP TO ADD STOPS · ESC/BACK TO CANCEL';}
function transitOfficePanel(){
 const state=ensureTransit(),depots=G.buildings.filter(b=>b.kind==='transit_depot'),stations=G.buildings.filter(b=>b.kind==='elevated_station'),d=transitDraft?.town===G?transitDraft:null;
 let html=`<div class="council-card transit-office"><h3>City transit</h3><p class="desc">Build a depot, choose a bus corridor, then tap street stops and review the capital and daily wage bill. Elevated metro uses roadside stations and guideway over existing streets. Passengers walk up to five street tiles and can transfer between routes.</p><div class="statgrid">${stat('Passenger journeys today',state.daily.rides)}${stat('Peak passengers left behind',state.daily.denied)}${stat('Fares today',money(state.daily.revenue))}${stat('Operating cost today',money(state.daily.expenses))}</div><div class="filter-row"><button data-build="transit_depot">DEPOT · ${money(buildCost.transit_depot)}</button><button data-build="elevated_station">ELEVATED STATION · ${money(buildCost.elevated_station)}</button><button data-transit-action="new-bus" ${depots.length?'':'disabled'}>NEW BUS ROUTE</button><button data-transit-action="new-elevated" ${depots.length&&stations.length>=2?'':'disabled'}>NEW ELEVATED ROUTE</button><button data-transit-action="overlay">${overlay==='transit'?'HIDE':'SHOW'} TRANSIT MAP</button></div><p class="desc">Each depot holds eight bus bays; each metro set needs two. Driver wages require available residents with basic skills and a street route to the depot. Fare: $0.65 bus / $1.25 metro, including transfers. Building a route authorizes its quoted daily operations; reduce or suspend service to save costs. The commuter-budget policy funds the legacy support service only while no public routes exist.</p>`;
 if(d){const quote=d.quote,reason=quote&&!quote.ok?quote.reason:'';html+=`<div class="entry"><strong>${d.editing>=0?'REPLAN':'PLAN'} ${TRANSIT_MODES[d.mode].name.toUpperCase()} · ${d.stops.length} stops</strong><label class="desc">Depot <select id="transitDepot" aria-label="Route depot">${depots.map(b=>`<option value="${b.id}" ${b.id===d.depot?'selected':''}>Depot ${b.id} · ${transitDepotLoad(b.id,d.editing)}/8 bays used</option>`).join('')}</select></label><label class="desc">Service <select id="transitLevel" aria-label="Route service level">${TRANSIT_LEVELS.slice(1).map((l,i)=>`<option value="${i+1}" ${i+1===d.level?'selected':''}>${l.name} · ${l.vehicles} vehicle${l.vehicles>1?'s':''}</option>`).join('')}</select></label><p class="desc">${d.stops.map((id,i)=>`${i+1}. ${d.mode==='bus'?esc(G.streetNames?.[id]||'Street')+' ('+id%T+','+(id/T|0)+')':'Station '+id}`).join(' → ')||'No stops yet. Select stops on the map.'}</p><div class="filter-row"><button data-transit-action="map">PICK STOPS ON MAP</button><button data-transit-action="undo" ${d.stops.length?'':'disabled'}>UNDO STOP</button><button data-transit-action="quote">REVIEW COST</button><button data-transit-action="cancel">CANCEL</button></div>${reason?`<p class="negative">${esc(reason)}</p>`:''}${quote?.ok?`<p class="desc">Simulation paused for review; use the clock control to resume. Capital due now <strong>${money(quote.cost)}</strong> · daily operations up to <strong>${money(quote.operating)}</strong><br>Peak capacity ${quote.capacity} one-way riders · ideal headway ${fmt(quote.headway)} minutes. Actual capacity falls with driver shortages or worn bus streets. Rails and stations remain after a route closes.</p>${renderTransitForecast(quote.forecast)}<button data-transit-action="build" ${G.treasury>=quote.cost?'':'disabled'}>AUTHORIZE ${d.editing>=0?'REVISED':'NEW'} ROUTE · ${money(quote.cost)}</button>`:''}</div>`;}
 for(const r of state.routes){const s=r.stats,occupancy=s.capacity?Math.round(s.reserved/s.capacity*100):0;html+=`<details class="entry" ${transitInspectorReport?.town===G&&transitInspectorReport.id===r.id?'open':''}><summary><strong style="color:${r.color}">● ${esc(r.name)}</strong> · ${esc(s.status)} · ${s.boardings||0} rides</summary><p class="desc">${r.stops.length} stops · ${TRANSIT_LEVELS[r.level].name} · ${r.vehicles} owned vehicle${r.vehicles>1?'s':''}<br>Drivers ${s.staff?.length||0}/${s.required||0} · reliability ${Math.round((s.reliability||0)*100)}% · headway ${fmt(s.headway||0)} min<br>Peak demand ${s.demand||0} · capacity ${s.capacity||0} · reserved ${occupancy}% · left behind ${s.denied||0}<br>Daily wages and maintenance ${money(s.expenses||0)} · capital invested ${money(r.capital)}<br>${s.denied?'Crowded: increase frequency or add a parallel corridor.':s.status.includes('driver')||s.status.includes('Driver')?'Recruitable drivers or operating cash are missing; increasing the fleet will not solve this.':'Connect homes to jobs and shops on different stops; a route with no useful destinations attracts no riders.'}</p>${transitInspectorReport?.town===G&&transitInspectorReport.id===r.id?renderTransitForecast(transitInspectorReport.report,true):''}<div class="filter-row"><button data-transit-action="report" data-route="${r.id}">REVIEW DEMAND & FUNDING</button>${TRANSIT_LEVELS.map((l,i)=>`<button data-transit-level="${r.id}:${i}" ${r.level===i?'disabled':''}>${l.name}</button>`).join('')}<button data-transit-action="edit" data-route="${r.id}">REPLAN STOPS</button><button data-transit-action="focus" data-route="${r.id}">SHOW ROUTE</button><button data-transit-action="retire" data-route="${r.id}">RETIRE & SELL FLEET · UP TO ${money(r.vehicles*TRANSIT_MODES[r.mode].vehicle*.4)}</button></div></details>`;}
 const unusedTrack=state.tracks.filter(id=>!state.routes.some(r=>r.mode==='elevated'&&r.path.includes(id))).length;
 if(unusedTrack)html+=`<button data-transit-action="remove-guideway">REMOVE ${unusedTrack} UNUSED GUIDEWAY TILES · 15% SALVAGE</button>`;
 if(depots.length||stations.length)html+=`<details><summary>Infrastructure and unused sites</summary>${[...depots,...stations].map(b=>`<div class="entry"><strong>${esc(types[b.kind].n)} ${b.id}</strong><small>${b.kind==='transit_depot'?transitDepotLoad(b.id)+'/8 bays committed':'Roadside passenger access'} · (${b.x},${b.y})</small><button data-inspect="${b.id}">VIEW SITE</button><button data-transit-action="remove-site" data-site="${b.id}" ${state.routes.some(r=>r.depot===b.id||r.mode==='elevated'&&r.stops.includes(b.id))?'disabled':''}>REMOVE UNUSED SITE · 15% SALVAGE</button></div>`).join('')}</details>`;
 return html+'</div>';
}
$('panelBody').addEventListener('change',e=>{if(!transitDraft)return;if(e.target.id==='transitDepot')transitDraft.depot=+e.target.value;else if(e.target.id==='transitLevel')transitDraft.level=+e.target.value;else return;transitDraft.quote=null;renderPanel('construction');});
$('panelBody').addEventListener('click',e=>{
 const b=e.target.closest('[data-transit-action],[data-transit-level]');if(!b)return;
 if(b.dataset.transitLevel){const [id,level]=b.dataset.transitLevel.split(':').map(Number),r=ensureTransit().routes.find(r=>r.id===id);if(level>0&&r&&TRANSIT_LEVELS[level].vehicles>r.vehicles){if(!paused)$('pause').click();startTransitDraft(r.mode,id);transitDraft.level=level;transitDraft.quote=transitReviewedQuote(transitDraft,id);renderPanel('construction');return;}if(!setTransitLevel(id,level))toast('Change unavailable: check depot space, funds and connected streets.');else save();renderPanel('construction');return;}
 const action=b.dataset.transitAction,id=+b.dataset.route;
 if(action==='new-bus'||action==='new-elevated'){startTransitDraft(action==='new-bus'?'bus':'elevated');}
 else if(action==='report'){showTransitDemandReport(id,b);return;}
 else if(action==='hide-report'){transitInspectorReport=null;}
 else if(action==='edit')startTransitDraft('bus',id);
 else if(action==='overlay'){overlay=overlay==='transit'?'none':'transit';dirty=true;}
 else if(action==='map'&&transitDraft){buildMode='transit_route';overlay='transit';closePanel();transitDraftHint();return;}
 else if(action==='undo'&&transitDraft){transitDraft.stops.pop();transitDraft.quote=null;dirty=true;}
 else if(action==='quote'&&transitDraft){if(!paused)$('pause').click();transitDraft.quote=transitReviewedQuote(transitDraft,transitDraft.editing);}
 else if(action==='cancel'){cancelTransitDraft();closeBuildTool();}
 else if(action==='build'&&transitDraft){const d=transitDraft;if(buildTransitRoute(d,d.quote,d.editing)){cancelTransitDraft();closeBuildTool();save();toast('Route authorized. Drivers and vehicles begin service on the next simulated day.');}else{if(!paused)$('pause').click();d.quote=transitReviewedQuote(d,d.editing);toast('Demand, staffing, budget or cost changed. Review the refreshed report before authorizing.');}}
 else if(action==='retire'){if(deleteTransitRoute(id)){save();toast('Route retired. Vehicles sold; stations and guideway retained.');}}
 else if(action==='remove-guideway'){if(removeUnusedGuideway()){save();toast('Unused guideway decommissioned. Used corridors were retained.');}}
 else if(action==='remove-site'){if(removeTransitFacility(+b.dataset.site)){save();toast('Unused site removed. Salvage returned to the treasury.');}}
 else if(action==='focus'){const r=ensureTransit().routes.find(r=>r.id===id);if(r){const cell=r.path[r.path.length/2|0],p=iso(cell%T,cell/T|0);cam.x=p[0];cam.y=p[1];overlay='transit';closePanel();dirty=true;return;}}
 updateHeader();renderPanel('construction');
});

// Link target for the mayor dashboard or any other scoped UI surface.
function showTransitDemandReport(id,opener=null){
 const report=transitRouteReport(id);if(!G.transit?.routes.some(r=>r.id===id)){toast(report.reason);return report;}
 transitInspectorReport={town:G,id,report};openPanel('construction',opener);$('panelBody').querySelector('[data-transit-report="'+id+'"]')?.scrollIntoView({block:'nearest'});return report;
}

// SOURCE: 71-trip-inspector.js
// A transport sample can be inspected without changing economic cargo or jobs.
let inspectedTrip=null;
function inspectTripAt(wx,wy){
 let nearest=null,distance=12/cam.zoom;
 for(const v of traffic){const p=vehiclePosition(v),d=Math.hypot(wx-p.x,wy-p.y);if(d<distance){nearest=v;distance=d;}}
 if(!nearest)return false;inspectedTrip={...nearest,path:nearest.path.slice()};openPanel('trip');dirty=true;return true;
}
function renderTripInspector(){
 if(!inspectedTrip)return tip('Tap a moving commuter or delivery on the map.');
 const live=traffic.find(v=>v.id===inspectedTrip.id),trip=live||inspectedTrip,from=readBuild(trip.from),to=readBuild(trip.to),shipment=(G.freight||[]).find(s=>s.id===trip.shipment);
 const label=b=>b?b.firm>=0?(G.firms[b.firm]?.name||types[b.kind].n):b.hh>=0?(G.households[b.hh]?.name+' household'):types[b.kind].n:'Former site';
 return head(trip.style==='truck'?'Delivery on the road':trip.style==='pedestrian'?'A resident on foot':'A resident’s journey')+tip(trip.reason||'Local service journey')+strip('Trip sample',live?'Travelling':'Completed or no longer sampled')+strip('Origin',label(from))+strip('Destination',label(to))+strip('Road segments',Math.max(0,trip.path.length-1))+(shipment?strip('Cargo in transit',fmt(shipment.qty)+' '+shipment.good)+strip('Delivery accounting',shipment.remaining+' simulated days remaining'):'')+tip('Visible trips sample real job assignments and paid cargo. The economy continues tracking residents and shipments when visual traffic is hidden.')+`<div class="btnrow">${from?`<button data-inspect="${from.id}">Inspect origin</button>`:''}${to?`<button data-inspect="${to.id}">Inspect destination</button>`:''}<button data-trip-close>Back to map</button></div>`;
}
function drawInspectedRoute(g){
 if(active!=='trip'||!inspectedTrip)return;const trip=traffic.find(v=>v.id===inspectedTrip.id)||inspectedTrip;
 g.save();g.strokeStyle='#f2d99c';g.lineWidth=3/cam.zoom;g.lineJoin='round';g.beginPath();trip.path.forEach((id,i)=>{const p=roadCenter(id);if(i)g.lineTo(...p);else g.moveTo(...p)});g.stroke();
 for(const id of [trip.path[0],fromEnd(trip.path)]){const p=roadCenter(id);g.fillStyle='#315e4b';g.beginPath();g.arc(...p,5/cam.zoom,0,Math.PI*2);g.fill();}g.restore();
}
document.addEventListener('click',e=>{if(e.target.closest('[data-trip-close]'))closePanel()});

