function musicControls(){return head('Music & atmosphere')+`<div class="council-card"><p class="desc">Ten original chamber pieces · about 47 minutes. The next piece reflects the town’s activity and your preferred character, with six recent pieces held out. Changes take effect between pieces. Music and effects have separate controls.</p><p><b>${esc(musicStatus())}</b></p><div class="btnrow"><button id="musicToggle" aria-pressed="${musicEnabled}">${musicEnabled?'MUSIC ON':'MUSIC OFF'}</button><button id="musicNext">NEXT PIECE</button>${musicError?'<button id="musicRetry">Retry music</button>':''}</div><label class="range">Music volume <input id="musicVolume" type="range" min="0" max="100" value="${Math.round(musicVolume*100)}" aria-label="Music volume"></label><label>Music character <select id="musicMood" aria-label="Music character">${[['adaptive','Follow the town'],['quiet','Quieter selections'],['lively','Livelier selections']].map(([id,label])=>`<option value="${id}" ${musicMood===id?'selected':''}>${label}</option>`).join('')}</select></label><details><summary>Original score & credits</summary><p class="desc">Original melodies, arrangements and offline synthesis for TownLedger, dedicated under CC0. No borrowed recordings or samples.</p>${MUSIC_TRACKS.map(t=>`<p class="desc">${esc(t.title)} · ${Math.round(t.seconds/60)} min</p>`).join('')}</details></div>`;}
const musicSettingsBase=renderSettingsFull;renderSettingsFull=function(){return musicControls()+musicSettingsBase();};
document.addEventListener('click',e=>{if(!e.isTrusted)return;musicGesture=true;const b=e.target.closest('button');if(b?.id==='musicToggle'){musicEnabled=!musicEnabled;rememberMusic();refreshMusic(true);renderPanel('settings');}else if(b?.id==='musicNext'){musicEnabled=true;rememberMusic();playMusicTrack(chooseMusicTrack());renderPanel('settings');}else if(b?.id==='musicRetry'){refreshMusic(true);renderPanel('settings');}else refreshMusic();},{capture:true});
document.addEventListener('input',e=>{if(e.target.id!=='musicVolume')return;musicVolume=clamp(+e.target.value/100,0,1);rememberMusic();setMusicVolumes();refreshMusic();});
document.addEventListener('change',e=>{if(e.target.id!=='musicMood')return;if(['adaptive','quiet','lively'].includes(e.target.value)){musicMood=e.target.value;rememberMusic();}});

// SOURCE: 96-council-programme.js
// Scenario programmes measure sustained outcomes; they do not grant free resources.
function programmeMetrics(){
 const households=G.households.filter(h=>h.people.length),latest=fromEnd(G.observations)||{},need=G.market?.consumedFood+G.market?.unmetFood;
 const recurring=['policeBudget','defenseBudget','healthBudget','educationBudget','aidBudget','energyAidBudget','outreachBudget','roadBudget','transitBudget','militiaBudget','serviceVoucherBudget'].reduce((n,k)=>n+(G.policy[k]||0),0)+G.people.filter(p=>!p.deceased&&!p.movedAway&&p.age>70).length*(G.policy.pensionDaily||0)+(G.policy.employmentSubsidy||0)*G.people.filter(p=>p.job>=0&&!p.commuteBlocked).length+G.debt*((G.policy.policyRate||0)/100+.015)/360+(G.regionalTrade?.reliefUntil>=G.day?108:0);
 return {employment:G.stats.employment||0,hardship:G.stats.hardship||0,food:need>0?100*G.market.consumedFood/need:0,medical:100*(G.serviceProvision?.health?.coverage??latest.medicalCoverage??0),school:100*(G.actualServiceFunding?.school??G.serviceProvision?.school?.coverage??latest.schoolCoverage??0),buffers:100*households.filter(h=>householdLiquidity(h)/h.people.length>=300).length/Math.max(1,households.length),reserve:Math.min(999,G.treasury/Math.max(1,recurring)),banks:G.banks.filter(b=>!b.closed&&bankEquity(b)>0).length,blocked:G.market?.blockedCommutes||0,training:(G.civicTrainingCompletions||0)+(G.privateTrainingCompletions||0),treasury:G.treasury,debt:G.debt};
}
const PROGRAMME_RULES={
 work:['Residents in work','employment',75,'min','%','economy','Inspect sales and margins before financing more jobs.'],
 food:['Essential food supplied','food',95,'min','%','economy','Check reachable shops, stock, retail staff and household buying power.'],
 hardship:['Households in hardship','hardship',15,'max','%','citizens','Inspect a struggling family; income, rent and access can bind differently.'],
 care:['Funded medical access','medical',65,'min','%','community','Compare reachable places, qualified staff and operating purchases.'],
 learning:['Funded school access','school',60,'min','%','community','Buildings need reachable pupils, staff and sustained operating funds.'],
 cash:['Authorized spending reserve','reserve',30,'min',' days','treasury','Reserve days compare cash with authorized services, pensions, subsidy and debt interest. Unused allocations can make actual spending lower.'],
 banks:['Solvent operating banks','banks',2,'min','','banking','Default losses absorb equity; new banks need subscribed regional capital.'],
 buffers:['Families with $300 per resident','buffers',75,'min','%','citizens','Cash and bank deposits count; home valuations are not immediately spendable.'],
 access:['Interrupted work journeys','blocked',0,'max','','construction','Reconnect workplaces and homes before adding capacity.'],
 training:['Adult training terms completed','training',2,'min','','community','A term needs 120 equivalent locally funded school days; partial coverage takes longer.']
};
function programmeRule(key,target){const a=PROGRAMME_RULES[key];return {key,label:a[0],metric:a[1],target:target??a[2],direction:a[3],unit:a[4],panel:a[5],help:a[6]};}
function programmeChapter(title,description,keys,days=30){return {title,description,days,rules:keys.map(k=>Array.isArray(k)?programmeRule(...k):programmeRule(k))};}
const SCENARIO_PROGRAMMES={
 settlement:{title:'Build a lasting borough',chapters:[programmeChapter('The everyday essentials','Establish reliable work and a food basket families can obtain.',['work','food','hardship']),programmeChapter('Care within reach','Purchase usable care and teaching, then retain a month of authorized commitments.',['care','learning','cash']),programmeChapter('Prosperity with a cushion','Sustain useful services and family buffers through a longer operating period.',['work','buffers','care','learning','cash'],60)]},
 frontier:{title:'An independent frontier',chapters:[programmeChapter('A viable foothold','Secure the smaller town’s essentials before promising a larger public establishment.',[['work',65],'food',['hardship',25]]),programmeChapter('A modest public settlement','Expand care and learning within a thin tax base.',[['care',50],['learning',45],['cash',20]]),programmeChapter('Room to endure','Retain household buffers, reachable employment and a month of public commitments.',[['work',80],'buffers','access','cash'],60)]},
 hardtimes:{title:'A recovery that lasts',chapters:[programmeChapter('Stop the immediate slide','Restore essentials and retain access to solvent institutions.',[['work',70],'food',['hardship',25],'banks']),programmeChapter('Rebuild the cushions','Rebuild family savings while restoring funded local care and schooling.',['buffers',['care',50],['learning',45]]),programmeChapter('A durable recovery','Sustain employment and services without consuming the public cash reserve.',[['work',80],['hardship',12],'care','learning','cash'],90)]},
 industrial:{title:'An industrial social contract',chapters:[programmeChapter('Work that sustains families','Judge industrial expansion by paid work and essential living conditions.',[['work',80],'food','hardship']),programmeChapter('Skills behind the factories','Support actual adult training and reachable public care.',['training','learning','care']),programmeChapter('Investment with resilience','Keep the workforce connected and retain family and public buffers.',['work','access','buffers','cash'],60)]},
 regional:{title:'A city beyond full employment',chapters:[programmeChapter('An accessible regional city','A strong headline job market still needs reachable work and funded local places.',['access','care','learning']),programmeChapter('Broader capability','Complete sustained adult learning while families retain liquid savings.',['training','buffers',['learning',70]]),programmeChapter('A sustainable civic settlement','Carry the commitments through two months with a public reserve.',['work',['care',75],['learning',70],'cash'],60)]}
};
function programmeDefinition(){return owns(SCENARIO_PROGRAMMES,G.scenario)?SCENARIO_PROGRAMMES[G.scenario]:SCENARIO_PROGRAMMES.settlement;}
function initializeScenarioProgramme(){G.scenarioProgramme={version:1,scenario:G.scenario,started:G.day,stage:0,held:0,lastDay:G.day,completed:[],baseline:programmeMetrics()};}
function ensureScenarioProgramme(){if(!G.scenarioProgramme)initializeScenarioProgramme();}
function programmeRuleMet(rule,metrics){return rule.direction==='min'?metrics[rule.metric]+.00001>=rule.target:metrics[rule.metric]-.00001<=rule.target;}
function updateScenarioProgramme(){
 ensureScenarioProgramme();const state=G.scenarioProgramme,definition=programmeDefinition(),chapter=definition.chapters[state.stage];if(!chapter||state.lastDay===G.day)return;
 const metrics=programmeMetrics();state.lastDay=G.day;state.held=chapter.rules.every(r=>programmeRuleMet(r,metrics))?state.held+1:0;
 if(state.held<chapter.days)return;
 state.completed.push({stage:state.stage,day:G.day});state.stage++;state.held=0;state.baseline=metrics;
 const final=state.stage===definition.chapters.length,message=final?'Council programme completed: '+definition.title+'. The town remains open for continued government.':'Council chapter completed: '+chapter.title+'. Next: '+definition.chapters[state.stage].title+'.';
 G.journal.push({day:G.day,name:final?'Council programme complete':'Council chapter complete',message,baseline:{...G.stats,treasury:G.treasury}});story(message,'good');
}
function validateScenarioProgramme(data){
 if(data.scenario!=null&&!owns(SCENARIO_PROGRAMMES,data.scenario))return false;
 if(data.civicTrainingCompletions!=null&&(!Number.isInteger(data.civicTrainingCompletions)||data.civicTrainingCompletions<0||data.civicTrainingCompletions>1000000))return false;
 const p=data.scenarioProgramme;if(p==null)return true;const definition=SCENARIO_PROGRAMMES[data.scenario]||SCENARIO_PROGRAMMES.settlement;
 if(p.version!==1||p.scenario!==data.scenario||!Number.isInteger(p.started)||p.started<1||p.started>data.day||!Number.isInteger(p.lastDay)||p.lastDay<p.started||p.lastDay>data.day||!Number.isInteger(p.stage)||p.stage<0||p.stage>definition.chapters.length||!Number.isInteger(p.held)||p.held<0||p.held>=(definition.chapters[p.stage]?.days||1)||!Array.isArray(p.completed)||p.completed.length!==p.stage)return false;
 if(p.completed.some((c,i)=>c.stage!==i||!Number.isInteger(c.day)||c.day<p.started||c.day>data.day||(i>0&&c.day<=p.completed[i-1].day)))return false;
 return p.baseline&&typeof p.baseline==='object'&&!Array.isArray(p.baseline)&&Object.keys(p.baseline).length<=20&&['employment','hardship','food','medical','school','buffers','reserve','banks','blocked','training','treasury','debt'].every(k=>Number.isFinite(p.baseline[k])&&p.baseline[k]>=0);
}
function programmeTrend(){
 const samples=G.observations.filter(o=>Number.isFinite(o.medicalCoverage)&&Number.isFinite(o.schoolCoverage)).slice(-36);if(samples.length<2)return tip('The ten-day record will begin to show trends after two observations.');
 const lines=[['employment','Employment','#536c70',1],['medicalCoverage','Medical access','#2f6945',100],['schoolCoverage','School access','#886020',100]],path=(key,scale)=>samples.map((s,i)=>`${(i/(samples.length-1)*320).toFixed(1)},${(110-clamp(s[key]*scale,0,100)).toFixed(1)}`).join(' ');
 return `<svg class="programme-chart" viewBox="0 0 355 135" role="img" aria-label="Employment, funded medical access and school access on a fixed zero to one hundred percent scale, days ${samples[0].day} to ${fromEnd(samples).day}"><path d="M0 10H320M0 60H320M0 110H320" stroke="#b2ba9c" fill="none"/>${lines.map(([key,label,color,scale])=>`<polyline points="${path(key,scale)}" fill="none" stroke="${color}" stroke-width="2.5"/>`).join('')}<g fill="#344d3d" font-size="10"><text x="325" y="14">100%</text><text x="325" y="64">50%</text><text x="325" y="114">0%</text><text x="0" y="132">DAY ${samples[0].day}</text><text x="255" y="132">DAY ${fromEnd(samples).day}</text></g></svg><div class="programme-legend">${lines.map(([key,label,color,scale])=>`<span><i style="background:${color}"></i>${label} ${policyNumber(fromEnd(samples)[key]*scale)}%</span>`).join('')}</div>`;
}
function scenarioProgrammeCard(full=false){
 const state=G.scenarioProgramme;if(!state)return '';const definition=programmeDefinition(),chapter=definition.chapters[state.stage],metrics=programmeMetrics();
 const heading=chapter?chapter.title:'Programme complete',progress=chapter?state.held/chapter.days:1;
 let html=`<section class="programme-card ${full?'full':'compact'}" aria-label="Council programme"><small>COUNCIL PROGRAMME · ${state.stage===3?'COMPLETED':'CHAPTER '+(state.stage+1)+' OF 3'}</small><h3>${esc(full?definition.title:heading)}</h3>${full?`<strong>${esc(heading)}</strong><p class="desc">${esc(chapter?.description||'The programme has been sustained. Keep governing, try another ambition, or export a record of this town.')}</p>`:''}<div class="progress" role="progressbar" aria-label="Sustained qualifying days" aria-valuemin="0" aria-valuemax="${chapter?.days||1}" aria-valuenow="${chapter?state.held:1}"><i style="width:${Math.round(progress*100)}%"></i></div>`;
 if(chapter){html+=`<p class="miniNote">${state.held} / ${chapter.days} consecutive qualifying days.${full?' Missing a condition resets this chapter’s count; completed chapters remain recorded.':''}</p>`;
 html+=chapter.rules.map(r=>`<div class="programme-rule ${programmeRuleMet(r,metrics)?'met':'waiting'}"><span class="programme-state">${programmeRuleMet(r,metrics)?'MET':'NEEDS WORK'}</span><div><strong>${esc(r.label)}</strong><span>${policyNumber(metrics[r.metric])}${r.unit} / ${r.direction==='min'?'at least':'at most'} ${r.target}${r.unit}</span></div><button data-programme-panel="${r.panel}" title="${esc(r.help)}" aria-label="${esc(r.label+': '+r.help)}">Review</button></div>`).join('');
 html+=`<details><summary>How to work on this chapter</summary><p class="desc">${esc(chapter.description)} Missing a condition resets this chapter’s qualifying-day count. Completed chapters remain recorded.</p>${chapter.rules.map(r=>`<p class="desc"><strong>${esc(r.label)}.</strong> ${esc(r.help)}</p>`).join('')}<p class="desc">This is an observed programme, not a forecast. Recruitment takes 30 days; training needs 120 funded teaching days; equipment commissions 30 days after payment. A budget cannot create a missing road or qualified worker instantly.</p></details>`;
 }
 if(full)html+=head('Observed outcomes')+programmeTrend()+tip('The shared scale is 0–100%. These are observed outcomes, including other influences; a policy change is not a controlled experiment.')+head('The full programme')+definition.chapters.map((c,i)=>`<div class="programme-chapter"><span>${i<state.stage?'COMPLETED DAY '+state.completed[i].day:i===state.stage?'CURRENT':'LATER CHAPTER'}</span><strong>${i+1}. ${esc(c.title)}</strong><p class="desc">${esc(c.description)} Sustain all conditions ${c.days} days.</p>${i===state.stage?'':c.rules.map(r=>`<small>${esc(r.label)}: ${r.direction==='min'?'at least':'at most'} ${r.target}${r.unit}</small>`).join('')}</div>`).join('');
 return html+'</section>';
}
const programmeOverviewBase=renderOverviewFull;renderOverviewFull=function(){return scenarioProgrammeCard()+programmeOverviewBase();};
const programmeAgendaBase=renderAgenda;renderAgenda=function(){return scenarioProgrammeCard(true)+programmeAgendaBase();};
document.addEventListener('click',e=>{const b=e.target.closest('[data-programme-panel]');if(b){openPanel(b.dataset.programmePanel);$('panelBody').scrollTop=0;}});

// SOURCE: 97-workday-scenes.js
// Original small workday tableaux. They visualize actual operating activity;
// samples never create cargo, income, pupils or production in the simulation.
function workdayScenes(items){
 if(!visualDetailBudget().people||!gameOptions.decor||gameOptions.quality==='low')return [];
 const scenes=[],cap=fastRenderEnabled()?3:gameOptions.quality==='high'?12:7;
 for(let n=items.length-1;n>=0;n--){const item=items[n],b=item.b;if(!b||scenes.length>=cap)continue;const f=G.firms[b.firm];let scene=null;
  if(f&&!f.closed&&workingStaff(f).length&&f.production>0){if(['mill','sawmill','factory'].includes(b.kind))scene='machinery';else if(['farm','fishery','forestry'].includes(b.kind))scene='harvest';}
  if(f&&!f.closed&&b.kind==='wharf'&&workingStaff(f).length&&(f.cargoToday||0)>0)scene='loading';
  if(b.kind==='clinic'&&G.serviceProvision?.health?.paid>0&&G.serviceProvision.health.coverage>0)scene='care';
  if(b.kind==='school'&&(f?.privateService==='school'?!f.closed&&(f.clientsToday||0)>0:G.serviceProvision?.school?.paid>0&&G.serviceProvision.school.coverage>0))scene='teaching';
  if(b.kind==='worksite'||b.redevelopment){const p=G.projects.find(p=>p.id===b.id);if(p&&!p.reason&&p.remaining>0)scene='construction';}
  if(!scene)continue;const front=point(item.w*.10,item.d*.48,0),portal=graph().portals.get(b.id),road=portal==null?null:roadCenter(portal);const x=road&&road[1]>=item.y?item.x*.35+road[0]*.65:item.x+front[0],y=road&&road[1]>=item.y?item.y*.35+road[1]*.65:item.y+front[1];scenes.push({kind:'workday',scene,b,f,x,y,dx:1,dy:.5});
 }
 return scenes;
}
function paintWorkdayScene(g,a,clock){
 const phase=clock+a.b.id*.17,x=Math.round(a.x),y=Math.round(a.y),skin=['#d6b38b','#c79570','#9d7358'][a.b.id%3];
 g.save();g.translate(x,y);g.fillStyle='#304b4530';g.beginPath();g.ellipse(0,2,16,4,.2,0,Math.PI*2);g.fill();
 const person=(px,py,color,scale=1,working=false)=>{g.save();g.translate(Math.round(px),Math.round(py));g.scale(scale,scale);const reach=working?Math.sin(phase*3)*2:0;
  g.fillStyle='#374e43';g.fillRect(-2,-2,2,4);g.fillRect(1,-1,2,3);g.fillStyle=color;g.fillRect(-3,-9,6,8);g.fillStyle=tone(color,.75);g.fillRect(2,-8,2,7);g.fillStyle=skin;g.fillRect(-2,-14,5,5);g.fillRect(-5,-8+reach,2,5);g.fillRect(4,-8-reach,2,5);g.fillStyle='#6a5a41';g.fillRect(-3,-15,7,2);g.restore();};
 if(a.scene==='machinery'){
  // A cast-iron flywheel and a short handling bench share one drive phase.
  polygon(g,[[-16,-4],[-3,-9],[14,-1],[1,5]],'#aa9674');segment(g,[-14,-2],[-14,5],'#6d7160',2);segment(g,[12,0],[12,7],'#6d7160',2);
  g.save();g.translate(-6,-10);g.transform(.85,.42,0,1,0,0);g.strokeStyle='#565f53';g.lineWidth=3;g.beginPath();g.arc(0,0,8,0,Math.PI*2);g.stroke();g.strokeStyle='#b2ad86';g.lineWidth=1;g.beginPath();g.arc(0,0,6,0,Math.PI*2);g.stroke();
  for(let j=0;j<6;j++){const turn=phase*1.8+j*Math.PI/3;segment(g,[0,0],[Math.cos(turn)*6,Math.sin(turn)*6],'#7d856c',1.5);}g.fillStyle='#d0bb83';g.fillRect(-2,-2,4,4);g.restore();
  const drift=(phase*.35)%1;if(a.b.kind==='sawmill'){segment(g,[0+drift*6,-5],[12+drift*6,1],'#b19464',4);segment(g,[1+drift*6,-6],[13+drift*6,0],'#d0b583',1);}else{polygon(g,[[3,-7],[9,-10],[14,-7],[8,-4]],'#c2ad7d');polygon(g,[[3,-7],[8,-4],[8,1],[3,-2]],'#9f895d');polygon(g,[[8,-4],[14,-7],[14,-2],[8,1]],'#ad996c');}
  person(14,8,'#6f8271',.86,true);
 }else if(a.scene==='harvest'){
  person(-5+Math.sin(phase*.6)*3,0,'#9c8054',.93,true);g.fillStyle='#ad8d5d';g.fillRect(5,-4,8,5);g.fillStyle='#d3be87';g.fillRect(5,-5,8,2);
  if(a.b.kind==='fishery'){segment(g,[-5,-9],[5,-21+Math.sin(phase)*1.2],'#b3a37a');segment(g,[5,-21+Math.sin(phase)*1.2],[11,-3],'#ddd7b099');}else for(let j=0;j<3;j++){segment(g,[6+j*2,-5],[6+j*2,-10],'#b8ad65');g.fillStyle='#d2bd72';g.fillRect(5+j*2,-11,3,3);}
 }else if(a.scene==='loading'){
  const step=(phase*.22)%1;person(-12+step*20,step*6,'#718b80',.93,true);g.fillStyle='#c8aa72';g.fillRect(-14+step*20,-5+step*6,7,5);segment(g,[-13+step*20,-4+step*6],[-8+step*20,-2+step*6],'#8d7854');box(g,.12,.12,.13,.11,0,5,'#b69a65');
 }else if(a.scene==='care'){
  person(-7,0,'#d3d8c3',.97,true);g.fillStyle='#477b66';g.fillRect(-9,-8,4,1);person(8,5+Math.sin(phase*.5),'#8b7765',.87);g.fillStyle='#c7b587';g.fillRect(0,-2,5,4);g.fillStyle='#607d6b';g.fillRect(1,-1,3,1);
 }else if(a.scene==='teaching'){
  person(-7,-1,'#687e77',1,true);person(3,5,'#ab8b60',.72);person(12,9,'#84956a',.70);segment(g,[-11,-11],[-1,-7],'#c7b994',2);
 }else{
  person(-5,1,'#9c855b',.93,true);g.fillStyle='#dbc183';g.fillRect(-8,-14,7,3);const angle=Math.sin(phase*3)*.65;segment(g,[-1,-9],[6+angle*4,-16+angle*5],'#7b6f52',2);segment(g,[3+angle*4,-17+angle*5],[9+angle*4,-15+angle*5],'#66776e',3);polygon(g,[[6,2],[13,-1],[18,2],[11,5]],'#b9a27b');
 }
 g.restore();
}

// SOURCE: 98-alternative-suppliers.js
// UI selection exposes real alternatives; forecasts and settlements remain authoritative.
let supplierSelection={market:'port',good:'food',firm:null};
function regionalReviewStamp(f,m,good){const p=regionalContractForecast(f,m,good),q=p.quote;return JSON.stringify([f.closed,f.cash,f.stock[good]||0,regionalMarketQuote(m,good,'exports'),q?.freight,q?.days,p.reserve,p.existing,p.suggested,p.ceiling,p.production]);}
function alternativeSupplierPanel(){
 const m=OUTSIDE_MARKETS.find(m=>m.id===supplierSelection.market)||OUTSIDE_MARKETS[0],good=owns(m.exports,supplierSelection.good)?supplierSelection.good:Object.keys(m.exports)[0],firms=G.firms.filter(f=>!f.closed&&formulas[f.kind]?.out===good),f=firms.find(f=>f.id===supplierSelection.firm)||firms[0];
 supplierSelection={market:m.id,good,firm:f?.id??null};let detail;
 if(!f)detail='<p class="desc">This buyer seeks '+esc(good)+', but no current local producer of that commodity is open. Inspect production and land permissions; buyer demand has not disappeared.</p>';
 else{const p=regionalContractForecast(f,m,good),q=p.quote,price=regionalMarketQuote(m,good,'exports')*1.08,unit=f.unitCost?.[good]||marketPrice(good),size=p.suggested,active=ensureRegionalTrade().contracts.filter(c=>c.status==='active').length;
 const reason=!q?'No connected regional freight road.':!p.dispatchDays?'No usable dispatch days remain in the standard window.':f.cash<=0?'No enterprise working cash for freight.':p.suggested<10?'The forecast supports fewer than ten additional units after retained stock, existing promises, handling and freight cash.':'A forecast-sized review is available; future output and arrival remain uncertain.';
 detail=`<p class="desc"><b>${esc(reason)}</b></p><div class="statgrid">${stat('Held / retained units',policyNumber(f.stock[good]||0)+' / '+policyNumber(p.reserve))}${stat('Already promised units',policyNumber(p.existing))}${stat('Forecast / suggested units',policyNumber(p.estimate)+' / '+size)}${stat('Freight cash available',money(f.cash))}</div><p class="desc">${esc(f.name)} → ${esc(m.name)}. Quote ${mayorUnitMoney(price)}/unit; freight ${q?mayorUnitMoney(q.freight)+'/unit':'unavailable'}. Suggested-size inventory margin ${q?money((price-unit-q.freight)*size):'unavailable'} excludes future payroll, tax and disruption. ${policyNumber(p.production)} recent output/day, ${p.dispatchDays} usable dispatch days; standard deadline day ${G.day+30}. Food and other working reserves are retained. Priority dispatch can reduce stock for local buyers. Estimates assume current inputs, attendance, cash and routes persist.</p><button data-trade-offer="${m.id}" data-trade-firm="${f.id}" data-trade-good="${good}" ${!q||active>=3?'disabled':''}>Review this supplier’s ${esc(good)} promise</button>${active>=3?'<p class="desc">Three agreements are already active. Review their obligations before another commitment.</p>':''}`;}
 return `<details id="alternativeSuppliers" class="council-card"><summary>Compare other suppliers and commodities · including food</summary><label>Regional buyer <select id="supplierMarket">${OUTSIDE_MARKETS.map(v=>`<option value="${v.id}" ${v.id===m.id?'selected':''}>${esc(v.name)}</option>`).join('')}</select></label><label>Commodity the buyer seeks <select id="supplierGood">${Object.keys(m.exports).map(v=>`<option ${v===good?'selected':''}>${esc(v)}</option>`).join('')}</select></label><label>Local producer <select id="supplierFirm" ${firms.length?'':'disabled'}>${firms.length?firms.map(v=>`<option value="${v.id}" ${v===f?'selected':''}>${esc(v.name)}</option>`).join(''):'<option>No open producer</option>'}</select></label>${detail}</details>`;
}
document.addEventListener('change',e=>{if(!['supplierMarket','supplierGood','supplierFirm'].includes(e.target.id)||!G)return;if(e.target.id==='supplierMarket'){supplierSelection.market=e.target.value;supplierSelection.firm=null;}if(e.target.id==='supplierGood'){supplierSelection.good=e.target.value;supplierSelection.firm=null;}if(e.target.id==='supplierFirm')supplierSelection.firm=+e.target.value;const id=e.target.id;renderPanel('economy');const details=$('alternativeSuppliers');if(details)details.open=true;$(id)?.focus();});
const supplierResetBase=resetTownTransientUI;resetTownTransientUI=function(){supplierSelection={market:'port',good:'food',firm:null};supplierResetBase();};

// SOURCE: 98-charter-ui.js
function charterPlan(){return `<svg class="charter-plan" viewBox="0 0 130 130" role="img" aria-label="Original town and twenty-one adjoining regional districts"><rect x="0" y="0" width="56" height="56" fill="#78946b" stroke="#344f3d" stroke-width=".5"/>${ANNEX_PARCELS.map(p=>`<rect x="${p.x}" y="${p.y}" width="${p.w}" height="${p.h}" fill="${G.charter.owned.includes(p.id)?'#78946b':p.id===parcelFocus?'#d4b873':'#d7d3b3'}" stroke="#536c4b" stroke-width=".5"/>`).join('')}<path d="M5 0 4 18 6 30 4 49 5 65 4 80" stroke="#7baba4" stroke-width="3" fill="none"/><ellipse cx="66" cy="22" rx="6" ry="8" fill="#7baba4"/><text x="18" y="29" font-size="4" fill="#fff3d5">ORIGINAL TOWN</text></svg>`;}
function charterPanel(){
 const area=CHARTER_BASE*CHARTER_BASE+ANNEX_PARCELS.filter(p=>G.charter.owned.includes(p.id)).reduce((n,p)=>n+p.w*p.h,0);
 return `<details id="charterOffice" class="charter-accordion"><summary>Expand the borough · ${ANNEX_PARCELS.length-G.charter.owned.length} districts available</summary>`+head('Expand the borough')+`<section class="charter-office"><h3>New land, a real civic commitment</h3><p class="desc">The original 56 × 56 town retains its rights. Twenty-one substantial outer districts extend this bounded region to 128 × 128, through successive purchases. A deed makes new land available for development; it does not create roads, workers, utilities or service coverage. Existing private property titles remain unchanged.</p>${charterPlan()}${strip('Chartered surface',fmt(area)+' regional tiles')}${strip('Outer districts acquired',G.charter.owned.length+' / '+ANNEX_PARCELS.length)}<div class="btnrow"><button data-charter-overview>View regional boundaries</button><button data-charter-home>Return to town</button></div></section>`+
 ANNEX_PARCELS.map(p=>{const q=parcelSurvey(p),owned=G.charter.owned.includes(p.id),near=parcelAdjacent(p),deed=G.charter.deeds.find(d=>d.id===p.id);return `<section class="charter-district ${p.id===parcelFocus?'selected':''}" data-parcel-card="${p.id}"><small>${owned?'DEED RECORDED':near?'REGIONAL LAND AVAILABLE':'ADJOINING DEED REQUIRED'}</small><h3>${esc(p.name)}</h3><p class="desc">${esc(p.description)}</p>${strip('District surface',q.area+' tiles · '+p.w+' × '+p.h)}${strip('Land / water',q.land+' / '+q.water+' tiles')}${strip(owned?'Price paid':'Development-rights price',money(owned?deed.price:q.price))}${owned?strip('Acquired','Day '+deed.day):tip(near?'A connection from existing streets is still required. New households and firms face the usual utility bills, paid staffing and local service catchments.':'Acquire an adjoining district before extending into this belt.')}<div class="btnrow"><button data-parcel-preview="${p.id}">Preview district</button>${owned?'':`<button data-parcel-buy="${p.id}" ${!near||G.treasury<q.price?'disabled':''}>Review purchase · ${money(q.price)}</button>`}</div>${!owned&&G.treasury<q.price?`<p class="desc">Treasury shortfall: ${money(q.price-G.treasury)}. This is a one-time land outlay; retain funds for construction and recurring commitments.</p>`:''}</section>`;}).join('')+'</details>';
}
function revealCharterOffice(){const office=$('charterOffice');if(office)office.open=true;}
function previewParcel(id){const p=ANNEX_PARCELS.find(p=>p.id===id);if(!p)return;parcelFocus=id;overlay='charter';const center=iso(p.x+p.w/2,p.y+p.h/2);cam={x:center[0],y:center[1]+18,zoom:clamp(Math.min((cw-50)/((p.w+p.h)*36),(ch-100)/((p.w+p.h)*18)),.025,.55)};cam.y+=38/cam.zoom;closePanel();dirty=true;toast(p.name+': '+(G.charter.owned.includes(id)?'chartered land':'regional land · review its deed in Public Works'));}
function requestParcelPurchase(id){const p=ANNEX_PARCELS.find(p=>p.id===id);if(!p||G.charter.owned.includes(id)||!parcelAdjacent(p))return;const q=parcelSurvey(p),town=G;if(G.treasury<q.price){toast('Insufficient treasury for this district.');return;}
 showCustomEvent('LAND PURCHASE','Acquire '+p.name+'?',q.area+' new regional tiles, including '+q.land+' land and '+q.water+' water tiles. Pay '+money(q.price)+' to the regional land authority. Existing private titles stay intact. Roads, utilities, buildings and service staffing are separate commitments.',[{title:'Acquire the district',desc:'One-time price '+money(q.price)+'. The deed expands municipal development rights.',cost:q.price,apply:()=>{if(G!==town||!purchaseParcel(id,q.price)){toast('The quote is no longer valid. Review the district again.');return;}parcelFocus=id;openPanel('construction');revealCharterOffice();document.querySelector('[data-parcel-card="'+id+'"]')?.scrollIntoView({block:'start'});}},{title:'Keep the current boundary',desc:'No payment and no change to ownership.',apply:()=>{}}]);
}
let surveySignature='';
function updateRegionSurvey(){
 const signature=JSON.stringify([parcelFocus,G.charter?.owned]);if(signature===surveySignature)return;surveySignature=signature;
 $('surveyReview').disabled=!parcelFocus;$('surveyDistrict').innerHTML='<option value="" disabled '+(!parcelFocus?'selected':'')+'>Choose a district…</option>'+ANNEX_PARCELS.map((p,i)=>`<option value="${p.id}" ${parcelFocus===p.id?'selected':''}>${i+1}. ${esc(p.name)}${G.charter.owned.includes(p.id)?' · Owned':''}</option>`).join('');
}
function reviewSurveyDistrict(id){if(!ANNEX_PARCELS.some(p=>p.id===id))return;parcelFocus=id;openPanel('construction');revealCharterOffice();document.querySelector('[data-parcel-card="'+id+'"]')?.scrollIntoView({block:'start'});}
function charterLabelLayout(){
 const occupied=[],labels=[];for(const p of ANNEX_PARCELS.slice().sort((a,b)=>(b.id===parcelFocus)-(a.id===parcelFocus))){const index=ANNEX_PARCELS.indexOf(p),q=iso(p.x+p.w/2,p.y+p.h/2),x=cw/2+(q[0]-cam.x)*cam.zoom,y=ch/2+(q[1]-cam.y)*cam.zoom;
  let compact=cam.zoom<.20||parcelFocus!==p.id,text=(index+1)+'. '+p.name+(G.charter.owned.includes(p.id)?' · OWNED':'');
  const width=text.length*6.1+14;let box={x:x-width/2,y:y-11,w:width,h:22};
  if(occupied.some(a=>box.x<a.x+a.w+6&&box.x+box.w>a.x-6&&box.y<a.y+a.h+5&&box.y+box.h>a.y-5))compact=true;
  if(compact){text=String(index+1);box={x:x-11,y:y-11,w:22,h:22};}
  if(box.x<0||box.y<0||box.x+box.w>cw||box.y+box.h>ch)continue;
  if(occupied.some(a=>box.x<a.x+a.w+6&&box.x+box.w>a.x-6&&box.y<a.y+a.h+5&&box.y+box.h>a.y-5))continue;
  occupied.push(box);labels.push({p,index,text,compact,x,y,box});
 }return labels;
}
function charterSurveyTap(sx,sy,x,y){
 const label=charterLabelLayout().filter(a=>Math.abs(sx-a.x)<=Math.max(22,a.box.w/2)&&Math.abs(sy-a.y)<=22).sort((a,b)=>Math.hypot(sx-a.x,sy-a.y)-Math.hypot(sx-b.x,sy-b.y))[0],p=label?.p||parcelForTile(x,y);if(!p)return false;
 if(parcelFocus===p.id)reviewSurveyDistrict(p.id);else previewParcel(p.id);dirty=true;return true;
}
function drawCharterBounds(g){
 if(!G.charter)return;g.save();g.lineJoin='round';
 for(const p of ANNEX_PARCELS){const owned=G.charter.owned.includes(p.id);if(owned&&overlay!=='charter'&&parcelFocus!==p.id)continue;
  const points=[[p.x-.5,p.y-.5],[p.x+p.w-.5,p.y-.5],[p.x+p.w-.5,p.y+p.h-.5],[p.x-.5,p.y+p.h-.5]].map(([x,y])=>{const q=iso(x,y);return[q[0],q[1]+18]});
  g.strokeStyle=owned?'#bfd2a4':'#d4b777';g.lineWidth=(parcelFocus===p.id?2.5:1.2)/cam.zoom;g.setLineDash(owned?[]:[7/cam.zoom,5/cam.zoom]);g.beginPath();points.forEach((q,i)=>i?g.lineTo(...q):g.moveTo(...q));g.closePath();g.stroke();
 }
 if(overlay==='charter'||parcelFocus)for(const label of charterLabelLayout()){if(overlay!=='charter'&&label.p.id!==parcelFocus)continue;const q=iso(label.p.x+label.p.w/2,label.p.y+label.p.h/2),w=label.box.w/cam.zoom;
  g.font=(11/cam.zoom)+'px Arial';g.fillStyle=label.p.id===parcelFocus?'#e9cc8bed':'#f1ead3ed';g.fillRect(q[0]-w/2,q[1]-11/cam.zoom,w,22/cam.zoom);g.strokeStyle='#536c4b';g.lineWidth=1/cam.zoom;g.strokeRect(q[0]-w/2,q[1]-11/cam.zoom,w,22/cam.zoom);g.fillStyle='#29422e';g.textAlign='center';g.textBaseline='middle';g.fillText(label.text,q[0],q[1]);
 }
 g.setLineDash([]);g.restore();
}
$('surveyDistrict').addEventListener('change',e=>previewParcel(e.target.value));$('surveyReview').onclick=()=>reviewSurveyDistrict(parcelFocus||$('surveyDistrict').value);
const charterConstructionBase=renderConstructionFull;renderConstructionFull=function(){return charterPanel()+charterConstructionBase();};
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||!G)return;if(b.dataset.parcelPreview)previewParcel(b.dataset.parcelPreview);if(b.dataset.parcelBuy)requestParcelPurchase(b.dataset.parcelBuy);if(b.hasAttribute('data-charter-home')){overlay='none';parcelFocus=null;closePanel();centerTownCamera();}if(b.hasAttribute('data-charter-overview')){overlay='charter';parcelFocus=null;closePanel();const p=iso(T/2,T/2);cam={x:p[0],y:p[1]+18,zoom:Math.max(.025,Math.min((cw-24)/RW,(ch-100)/RH))};cam.y+=38/cam.zoom;dirty=true;}});

const charterBackBase=window.__townArchive.back;window.__townArchive.back=()=>{if(!active&&!pendingEvent&&$('helpDialog').style.display==='none'){if(buildMode){closeBuildTool();return true;}if(overlay==='charter'){overlay='none';parcelFocus=null;centerTownCamera();return true;}}return charterBackBase();};

// SOURCE: 98-district-ui.js
function districtProspectus(){return `<details class="council-card"><summary>District commitments & development programmes</summary><p class="desc">A deed buys geography; a charter chooses which new uses may compete for its lots. Existing titles remain intact. Initial designation is free; revision requires30 days and a$1,200 planning purchase. Completing30 days of connected district activity opens larger enterprise supply agreements, not free municipal cash.</p>`+ANNEX_PARCELS.map(p=>{const q=parcelSurvey(p),owned=G.charter.owned.includes(p.id),plan=G.districtProgrammes?.[p.id],m=owned?districtMetrics(p.id):null;return `<section class="council-card"><h3>${esc(p.name)}</h3><p class="desc">${q.forest} woodland tiles; ${q.water} water tiles. ${p.id==='river-reach'?'Open river frontage supports regional shipping; inland lakes do not.':p.id==='east-meadow'?'Lake frontage supports fishing and waterfront parks; it is not a regional cargo outlet.':p.id==='high-common'?'Requires an adjoining deed and a longer connection before utilities or shops become reachable.':'Transport and commuting require an actual street connection.'} For each100 new residents, fully purchased standard teaching and care require approximately ${money(100*10/260*Math.max(24,G.policy.minWage)/.65)} and ${money(100*5/350*Math.max(24,G.policy.minWage)/.65)} daily respectively, plus facilities, access and staff. These are planning estimates, not new automatic charges.</p>${!owned?`<button data-district-review="${p.id}">Review land deed</button>`:`<p class="desc">${m.pop} residents · ${m.staffed} staffed firms · ${m.connected} connected properties · care ${Math.round(m.care*100)}% · learning ${Math.round(m.school*100)}%.</p>${plan?`<b>${DISTRICT_FOCI[plan.focus].name} · ${plan.completed?'Established':plan.held+' /30 qualifying days'}</b><p class="desc">${DISTRICT_FOCI[plan.focus].goal}</p>`:''}${Object.entries(DISTRICT_FOCI).map(([key,f])=>`<details><summary>${esc(f.name)}</summary><p class="desc">${esc(f.description)} ${esc(f.goal)}</p><button data-district-focus="${key}" data-district-id="${p.id}" ${plan&&(plan.focus===key||G.day-plan.started<30)?'disabled':''}>${plan?'Review rezoning · $1,200':'Review district charter'}</button></details>`).join('')}`}</section>`}).join('')+'</details>'}
const districtConstructionBase=renderConstructionFull;renderConstructionFull=function(){return districtProspectus()+districtConstructionBase()};
document.addEventListener('click',e=>{const review=e.target.closest('[data-district-review]'),b=e.target.closest('[data-district-focus]');if(review)reviewSurveyDistrict(review.dataset.districtReview);if(b){const id=b.dataset.districtId,focus=b.dataset.districtFocus;showCustomEvent('DISTRICT PLANNING',DISTRICT_FOCI[focus].name,DISTRICT_FOCI[focus].description+' Existing properties remain legal. Revisions are available after30 days and cost$1,200.',[{title:'Record district charter',cost:0,apply:()=>chooseDistrictFocus(id,focus)}]);}});

// SOURCE: 98-migration-ui.js
// Readable push/pull reports; all quantities below are assessments or the bounded
// decisions observed since this town was opened, never invented census history.
function migrationPanel(){
 const report=migrationDiagnostics(),outside=report.outsideReference,inherited=G.tenancyVersion!==1||report.overcrowdedHomes.every(b=>b.legacySharedTenants.length>0);
 return `<details class="council-card" id="migrationOffice"><summary>Moving in, moving out & housing</summary><p class="desc">A new household needs an actual vacant unit, funded work it can reach, and take-home pay covering rent, food, utilities and fares. Existing local jobseekers get first consideration. Families also compare outside prices and local care/learning access. Affordable spare teaching places at working independent schools can also enter the forecast; their fees are included without assumed vouchers. A quoted job or place can change before arrival.</p><p class="desc">Outside comparison: ${esc(outside.name)} · ${money(outside.net)}/day reference income and ${money(outside.essentials)} essentials for two working adults. Income and rent use the founding-policy benchmark; food uses current market quotes. This is a comparison, not a guaranteed foreign job.</p>`+
 (report.reviewRequired?`<div class="entry"><strong>${inherited?'Inherited shared housing needs review':'Housing capacity needs review'}</strong><p class="desc">${report.overcrowdedHomes.length} dwellings have more households than physical units. Every existing family and financial claim is preserved. These addresses accept no further household arrivals. Commission real replacement housing and review relocation.</p><button data-urban-rehousing>Review replacement housing</button></div>`+report.overcrowdedHomes.slice(0,8).map(b=>`<button class="entry" data-inspect="${b.building}">${b.occupied} households · ${b.capacity} physical units · inspect address</button>`).join(''):'')+
 head('Observed population changes · since day '+report.observedSinceDay)+strip('Births / deaths',report.sessionCounts.births+' / '+report.sessionCounts.deaths)+strip('Immigration / emigration',report.sessionCounts.immigration+' / '+report.sessionCounts.emigration)+'<p class="desc">These observations restart after loading a town; no earlier census is reconstructed.</p>'+
 (report.recent.length?head('Recent decisions · this open session')+report.recent.slice(-5).reverse().map(row=>{const a=row.assessment;return `<div class="entry"><strong>${esc(row.kind.replace(/-/g,' '))} · day ${row.day}</strong>${a?`<p class="desc">Take-home ${money(a.expectedNet)}/day · essentials ${money(a.essentials)}/day${a.pullProbability!=null?' · current pull '+Math.round(a.pullProbability*100)+'%':''}. ${esc(a.reasons.join('; ')||'Funded reachable work and an affordable budget; outside alternatives and services still influence the choice.')}</p>`:''}</div>`;}).join(''):'<p class="desc">No migration decision has been observed since this town was opened. Earlier demographic history is not reconstructed from missing records.</p>')+'</details>';
}
const migrationCommunityBase=renderCommunityFull;renderCommunityFull=function(){return migrationPanel()+migrationCommunityBase();};
const migrationHouseholdReportBase=householdServiceReport;householdServiceReport=function(id){
 const h=G.households[id];if(!h?.people.length)return migrationHouseholdReportBase(id);const a=migrationEmigrationAssessment(h);
 return migrationHouseholdReportBase(id)+head('Household moving prospects')+strip('Actually spendable savings',money(a.spendable.spendable))+strip('Bank claims currently unavailable',money(a.spendable.locked))+strip('Expected net / essential costs',money(a.expectedNet)+' / '+money(a.essentials)+' per day')+`<p class="desc">${esc(a.reasons.join('; '))}. Outside comparison: ${esc(a.outside.name)}; reference-only earnings and housing, with current food quotes. Departing households keep their recorded property, debts and bank claims.</p>`;
};

// SOURCE: 98-onboarding-trade.js
function firstDeliveryCandidate(){return G.firms.filter(f=>!f.closed&&f.kind==='grocer'&&(f.stock.food||0)+pendingGoods(f,'food')<Math.max(100,reachableRetailDemand(f)*2)).map(f=>({f,q:OUTSIDE_MARKETS.map(m=>regionalQuote(f,m,'food','import')).filter(Boolean).sort((a,b)=>a.price+a.freight-b.price-b.freight)[0]})).find(o=>o.q&&o.f.cash>60*(o.q.price*(1+G.policy.importTariff/100)+o.q.freight))}
function tradingTownNextDecision(){const s=ensureRegionalTrade(),candidate=firstDeliveryCandidate(),active=s.contracts.some(c=>c.status==='active'),won=s.contracts.some(c=>c.status==='fulfilled');let body='';if(!s.delivered&&candidate){const {f,q}=candidate,cost=60*(q.price*(1+G.policy.importTariff/100)+q.freight);body=`<p class="desc">${esc(f.name)} needs a food buffer. Broker 60 units from ${esc(q.m.name)}: approximately ${money(cost)} of the enterprise’s cash, ${q.days} days to arrive. Imports buy reliability and outside competition; local production keeps more receipts with local suppliers.</p><div class="btnrow"><button id="firstFoodOrder" ${G.policy.imports?'':'disabled'}>Review an inbound food delivery</button><button id="firstLocalFood">Plan local food production</button></div>`}else if(!active&&!won){body=`<p class="desc">${s.delivered} regional deliveries completed. Your next choice is a limited supplier agreement: commit a surplus for a better quote, or keep inventory available for local buyers. The preview shows freight, stock and margin before committing.</p><button id="firstTradeAgreement">Compare a 30-day export agreement</button>`}else if(active){body='<p class="desc">An agreement is underway. Track cargo and local stocks; payment arrives with delivery. Compare commissioning a staffed logistics depot with keeping cash available for wages and imported inputs.</p><button id="firstTradeAgreement">Follow the commitment</button>'}else body='<p class="desc">A supplier agreement is fulfilled. Choose what the next district is for: a trade park that needs commuters, a mixed neighbourhood that needs care and teaching, or a working waterfront that reserves scarce shore plots. Larger agreements require an established district programme.</p><button id="firstDistrictPlan">Compare district commitments</button>';return `<section class="council-card"><h3>A trading town · your next decision</h3>${body}</section>`}
const tradingOverviewBase=renderOverviewFull;renderOverviewFull=function(){return tradingTownNextDecision()+tradingOverviewBase()};
document.addEventListener('click',e=>{if(e.target.closest('#firstTradeAgreement')){openPanel('economy');const b=document.querySelector('[data-trade-offer]:not([disabled])');b?.scrollIntoView({block:'center'})}if(e.target.closest('#firstLocalFood')){constructionCategory='production';openPanel('construction')}if(e.target.closest('#firstDistrictPlan')){openPanel('construction');const summary=document.querySelector('#panelBody summary');if(summary){summary.parentElement.open=true;summary.scrollIntoView({block:'center'})}}if(e.target.closest('#firstFoodOrder')){const o=firstDeliveryCandidate();if(!o||!G.policy.imports)return;const cost=60*(o.q.price*(1+G.policy.importTariff/100)+o.q.freight);showCustomEvent('FIRST DELIVERY','Working capital or local capacity?',o.f.name+' proposes 60 food from '+o.q.m.name+'. Estimated '+money(cost)+' from its cash; '+o.q.days+' simulated days in transit. This is enterprise inventory, not a free municipal grant. Local producers can still compete on landed price.',[{title:'Broker the inbound order',cost:0,apply:()=>{if(!G.policy.imports||o.f.closed)return;const n=dispatchRegional(o.f,'food',60,'import',regionalQuote(o.f,o.q.m,'food','import'));story(n>0?'A first food delivery is on the road to '+o.f.name+'. Follow the consignment in Economy.':'Loading or working capital is unavailable; no food order was placed.','neutral',o.f.building)}}]);}});

// SOURCE: 98-player-experience.js
// Mayor's desk: observed choices and earned milestones, never a second economy.
function mayorUnitMoney(value){return '$'+Number(value||0).toLocaleString('en-CA',{minimumFractionDigits:2,maximumFractionDigits:2});}
const TOWN_DIRECTIONS={
 exchange:{title:'The regional crossroads',promise:'Build a dependable trading town',tradeoff:'Imports can relieve shortages quickly, but tie up enterprise cash in transit and compete with local suppliers. Export agreements reserve stock before payment arrives.',steps:[
  ['A road to the wider world','Complete a regional delivery.','delivery','economy'],
  ['A promise kept','Fulfil a supplier agreement with real deliveries.','agreement','economy'],
  ['Room for enterprise','Establish a productive trade-park district.','industry','construction'],
  ['Trade that supports a town','Maintain 75% employment, 95% food supplied and 30 authorized spending days in reserve for 30 days.','resilient','treasury']]},
 river:{title:'The working river',promise:'Make scarce shore land earn its place',tradeoff:'Fishing supplies food within a shared catch limit. Freight needs a river outlet, attending workers and competitive orders; the inland lake cannot ship regional cargo.',steps:[
  ['Crews on the water','Establish a new staffed fishery beyond the businesses present when this direction began.','fishery','construction'],
  ['Cargo as well as catch','Establish a new staffed cargo wharf with a regional river outlet; inspect demand before commissioning.','wharf','construction'],
  ['A lasting waterfront','Establish a working-waterfront district.','waterfront','construction'],
  ['A river town for families','Maintain 95% food supplied, at most 15% hardship and 30 authorized spending days in reserve for 30 days.','riverLife','community']]},
 community:{title:'The complete neighbourhood',promise:'Grow a place where families can stay',tradeoff:'New land without reachable work, care and teaching creates a burden. Public provision spends municipal funds; private provision needs paying customers and access. Compare actual coverage before choosing either.',steps:[
  ['Daily essentials','Supply 95% of food need with at most 15% household hardship.','essentials','economy'],
  ['Care within reach','Achieve at least 65% funded medical access and 60% funded school access.','services','community'],
  ['Growth with a purpose','Establish a mixed-neighbourhood district.','neighbourhood','construction'],
  ['A secure next generation','Maintain 75% employment, 65% medical access, 60% school access and 30 authorized spending days in reserve for 30 days.','familyLife','community']]}
};
function blankMayorJourney(){return {version:1,direction:'',started:G.day,stage:0,held:0,lastDay:G.day,completed:[],guide:true,visited:[],review:null};}
function ensureMayorJourney(){if(!G.mayorJourney)G.mayorJourney=blankMayorJourney();return G.mayorJourney;}
function mayorJourneyView(){return G.mayorJourney||blankMayorJourney();}
function mayorMetrics(){
 const m=programmeMetrics(),trade=G.regionalTrade||{},plans=Object.values(G.districtProgrammes||{}),staffed=G.firms.filter(f=>!f.closed&&workingStaff(f).length>0);
 return {...m,delivery:(trade.delivered||0)>0,agreement:(trade.contracts||[]).some(c=>c.status==='fulfilled'),industry:plans.some(p=>p.focus==='industry'&&p.completed),waterfront:plans.some(p=>p.focus==='waterfront'&&p.completed),neighbourhood:plans.some(p=>p.focus==='neighbourhood'&&p.completed),fishery:staffed.some(f=>f.kind==='fishery'),wharf:staffed.some(f=>{const b=readBuild(f.building);return f.kind==='wharf'&&b&&waterfrontSite(b.x,b.y,'wharf')})};
}
function mayorDirectionBaseline(){const m=mayorMetrics();return {version:1,day:G.day,delivered:G.regionalTrade?.delivered||0,agreements:(G.regionalTrade?.contracts||[]).filter(c=>c.status==='fulfilled').map(c=>c.id),districts:Object.entries(G.districtProgrammes||{}).filter(([id,p])=>p.completed).map(([id,p])=>[id,p.focus,p.completedDay||p.started].join('|')),firms:G.firms.map(f=>f.id),essentials:mayorStepMet('essentials',m,null),services:mayorStepMet('services',m,null)};}
function mayorStepMet(key,m,journey=G.mayorJourney){
 const baseline=journey?.baseline;if(baseline){
  if(key==='delivery')return (G.regionalTrade?.delivered||0)>baseline.delivered;
  if(key==='agreement')return (G.regionalTrade?.contracts||[]).some(c=>c.status==='fulfilled'&&!baseline.agreements.includes(c.id));
  if(['industry','waterfront','neighbourhood'].includes(key))return Object.entries(G.districtProgrammes||{}).some(([id,p])=>p.focus===key&&p.completed&&!baseline.districts.includes([id,p.focus,p.completedDay||p.started].join('|')));
  if(['fishery','wharf'].includes(key))return G.firms.some(f=>f.kind===key&&!baseline.firms.includes(f.id)&&!f.closed&&workingStaff(f).length>0&&(key!=='wharf'||(()=>{const b=readBuild(f.building);return b&&waterfrontSite(b.x,b.y,'wharf');})()));
 }
 if(['delivery','agreement','industry','waterfront','neighbourhood','fishery','wharf'].includes(key))return !!m[key];
 if(key==='essentials')return m.food>=95&&m.hardship<=15;
 if(key==='services')return m.medical>=65&&m.school>=60;
 if(key==='resilient')return m.employment>=75&&m.food>=95&&m.reserve>=30;
 if(key==='riverLife')return m.food>=95&&m.hardship<=15&&m.reserve>=30;
 if(key==='familyLife')return m.employment>=75&&m.medical>=65&&m.school>=60&&m.reserve>=30;
 return false;
}
function mayorJourneyDay(){
 const p=ensureMayorJourney();if(p.lastDay===G.day)return;p.lastDay=G.day;
 const d=TOWN_DIRECTIONS[p.direction],s=d&&d.steps[p.stage];if(!s)return;
 const met=mayorStepMet(s[2],mayorMetrics());p.held=met?p.held+1:0;
 if(!met||p.held<(p.stage===3?30:1))return;
 const existingPrerequisite=!!p.baseline&&!!p.baseline[s[2]]&&['essentials','services'].includes(s[2]);p.completed.push({stage:p.stage,day:G.day,...(existingPrerequisite?{existingPrerequisite:true}:{})});p.stage++;p.held=0;
 story('Town direction: '+s[0]+(existingPrerequisite?' acknowledged as an existing prerequisite. ':' achieved through current work. ')+(p.stage===4?'The '+d.title.toLowerCase()+' record is complete. Keep governing or try another direction.':'Next: '+d.steps[p.stage][0]+'.'),'good');
}
function validateMayorJourney(data){
 const p=data.mayorJourney;if(p==null)return true;
 if(p.version!==1||!(p.direction===''||owns(TOWN_DIRECTIONS,p.direction))||!Number.isInteger(p.started)||p.started<1||p.started>data.day||!Number.isInteger(p.lastDay)||p.lastDay<p.started||p.lastDay>data.day||!Number.isInteger(p.stage)||p.stage<0||p.stage>4||(!p.direction&&p.stage!==0)||!Number.isInteger(p.held)||p.held<0||p.held>=30||typeof p.guide!=='boolean'||!Array.isArray(p.completed)||p.completed.length!==p.stage||!Array.isArray(p.visited)||p.visited.length>12||p.visited.some(k=>!['economy','businesses','community','construction','treasury','policies','journal','citizens','banking','agenda','overview','settings'].includes(k))||new Set(p.visited).size!==p.visited.length)return false;
 if(p.baseline){const b=p.baseline;if(b.version!==1||b.day!==p.started||!Number.isSafeInteger(b.delivered)||b.delivered<0||typeof b.essentials!=='boolean'||typeof b.services!=='boolean'||!Array.isArray(b.firms)||b.firms.length>data.firms.length||new Set(b.firms).size!==b.firms.length||b.firms.some(id=>!Number.isInteger(id)||!data.firms[id])||!Array.isArray(b.agreements)||b.agreements.length>24||new Set(b.agreements).size!==b.agreements.length||b.agreements.some(id=>!Number.isSafeInteger(id)||id<1)||!Array.isArray(b.districts)||b.districts.length>ANNEX_PARCELS.length||new Set(b.districts).size!==b.districts.length||b.districts.some(proof=>{if(typeof proof!=='string')return true;const [id,focus,day]=proof.split('|');return !ANNEX_PARCELS.some(p=>p.id===id)||!owns(DISTRICT_FOCI,focus)||!/^\d+$/.test(day)||+day<1||+day>b.day;}))return false;}
 if(p.completed.some((c,i)=>!c||c.existingPrerequisite!=null&&typeof c.existingPrerequisite!=='boolean'||c.stage!==i||!Number.isInteger(c.day)||c.day<p.started||c.day>data.day||(i>0&&c.day<p.completed[i-1].day)))return false;
 if(p.review!=null){const v=p.review;if(!Number.isInteger(v.day)||v.day<1||v.day>data.day||!v.metrics||!['employment','food','hardship','medical','school','reserve'].every(k=>Number.isFinite(v.metrics[k])&&v.metrics[k]>=0&&v.metrics[k]<=1000))return false;}
 return true;
}
function recentTradeSetbacks(){
 const contracts=G.regionalTrade?.contracts||[];return contracts.filter(c=>c.status==='missed'&&G.day>=c.deadline&&G.day-c.deadline<=90&&!contracts.some(next=>next.status==='fulfilled'&&next.market===c.market&&next.id>c.id&&next.deadline>=c.deadline)).sort((a,b)=>b.deadline-a.deadline);
}
function mayorPressureCards(){
 const m=mayorMetrics(),s=G.regionalTrade||{shipments:[],contracts:[]},issues=[];
 const add=(score,title,evidence,cause,panel,label)=>issues.push({score,title,evidence,cause,panel,label});
 if(G.day>1&&m.food<95)add(100,'Put food on the shelves',fmt(m.food)+'% of observed food need supplied','Compare shop stocks, purchasing power and inbound arrival dates. Imports buy a buffer; a local food chain needs workers and inputs.','economy','Compare food routes');
 if(m.reserve<30)add(95,'Protect the next month',fmt(m.reserve)+' days of authorized spending in cash','Review actual receipts, pensions and debt before adding recurring commitments. Borrowing buys time and adds interest.','treasury','Review the cash runway');
 if(m.blocked>0)add(90,'Reconnect paid work',fmt(m.blocked)+' interrupted work journeys','A missing connection can strand existing jobs. Repair access before paying for additional capacity.','construction','Review roads');
 if(m.hardship>15)add(85,'A pay packet is not enough',fmt(m.hardship)+'% of households in hardship','Inspect a family’s wages, rent, essentials and savings before choosing tax relief or targeted support.','citizens','Follow household accounts');
 if(G.day>1&&(m.medical<65||m.school<60))add(75,'Places need people and access','Care '+fmt(m.medical)+'% · learning '+fmt(m.school)+'%','More funding cannot instantly create a qualified worker or a road. Compare public capacity and available private providers before building.','community','Compare provision');
 const transit=G.transit?.daily;if(transit?.denied>0)add(82,'The passenger network is leaving riders behind',fmt(transit.denied)+' peak passengers without a place · '+fmt(transit.rides)+' actual journeys today','Compare the corridor’s actual driver attendance, peak capacity and operating bill. A larger fleet uses municipal capital and qualified workers who may also be needed by schools or businesses.','construction','Review the actual transit corridors');
 const delayed=(s.shipments||[]).filter(o=>o.due<G.day);if(delayed.length)add(92,'Cargo is taking longer',delayed.length+' consignments past expected arrival','Expected arrival is a plan. Review access, loading and buyer liquidity before promising another agreement.','economy','Trace the delay');
 const missed=recentTradeSetbacks();if(missed.length){const c=missed[0],market=OUTSIDE_MARKETS.find(m=>m.id===c.market);add(70,'Review a recent missed window',(market?.name||c.name)+' · '+fmt(c.delivered)+' / '+fmt(c.quantity)+' recorded arrivals; window ended day '+c.deadline,'The past window remains in history. Review uncommitted stock and handling before another promise. This is recent delivery evidence, not a hidden reputation score.','economy','Review the actual agreement');}
 if(G.day===1)add(40,'Take the first council session','Awaiting the first daily settlement','Trace food stocks and enterprise cash now. Let one simulated day finish before judging food and funded service coverage.','economy','Trace the supply chain');
 if(!issues.length)add(30,'Choose what growth is for',fmt(m.employment)+'% employment · '+fmt(m.reserve)+' reserve days','Compare a trade park, a mixed neighbourhood and river frontage. Land choice changes eligible activities and operating needs.','construction','Compare district commitments');
 return issues.sort((a,b)=>b.score-a.score).slice(0,3);
}
function mayorDesk(){
 const p=mayorJourneyView(),d=TOWN_DIRECTIONS[p.direction],s=d&&d.steps[p.stage];
 return `<section class="mayor-desk" aria-label="Mayor’s desk"><div class="mayor-heading"><small>YOUR MAYOR’S DESK · DAY ${G.day}</small><button data-mayor-agenda>Town direction →</button></div><h3>${esc(s?s[0]:d?'A direction earned':'What needs your decision?')}</h3>${s?`<p class="desc">${esc(!p.baseline&&['fishery','wharf'].includes(s[2])?'Legacy direction: operate the recorded staffed '+s[2]+'.':s[1])} ${p.stage===3?p.held+' / 30 consecutive qualifying days.':''}</p>`:''}<div class="mayor-pressure-grid">${mayorPressureCards().map(i=>`<article><strong>${esc(i.title)}</strong><b>${esc(i.evidence)}</b><button data-mayor-panel="${i.panel}">${esc(i.label)}</button><details><summary>Why this matters</summary><p class="desc">${esc(i.cause)}</p></details></article>`).join('')}</div>${p.guide?mayorGuide(p):`<button class="small" data-mayor-guide="show">Show the optional first council session</button>`}</section>`;
}
const MAYOR_GUIDE=[['economy','Trace one shortage','Compare available food, inbound cargo and the landed price. Return to Town Hall to review an inbound delivery when a suitable shop needs stock.'],['businesses','Meet the supplier','Open a firm and compare sales, payroll, inventory purchases and cash. A profitable quote can still need cash before the truck returns.'],['treasury','Price the commitment','Compare cash with recurring authorization before choosing a new service or district.'],['agenda','Choose a town direction','Pick a route that interests you. Earn progress through actual deliveries, services and connected district activity.']];
function mayorGuide(p){const next=MAYOR_GUIDE.find(x=>!p.visited.includes(x[0]));return `<details class="mayor-guide" ${next?'open':''}><summary>Optional first council session · ${MAYOR_GUIDE.filter(x=>p.visited.includes(x[0])).length} / 4 reports explored</summary>${next?`<strong>${esc(next[1])}</strong><p class="desc">${esc(next[2])}</p><button data-mayor-panel="${next[0]}">Open ${esc(next[1].toLowerCase())}</button>`:'<p class="desc">You have explored the decision loop. Keep a small promise, follow the delivery, then choose where to grow.</p>'}<button class="small" data-mayor-guide="hide">Hide guide</button></details>`;}
function mayorExistingWaterfrontAction(key){if(!['fishery','wharf'].includes(key))return '';const f=G.firms.find(f=>f.kind===key&&!f.closed&&readBuild(f.building));return f?'<button data-inspect="'+f.building+'">Inspect existing '+esc(types[key].n.toLowerCase())+' demand and accounts before competing</button>':'';}
function mayorDirectionPanel(){
 const p=mayorJourneyView(),d=TOWN_DIRECTIONS[p.direction],m=mayorMetrics();
 return `<section class="mayor-desk"><small>A TOWN WITH A PURPOSE</small><h3>${esc(d?d.title:'Choose your town’s next story')}</h3><p class="desc">A direction is an optional plan, not a policy preset. It spends no money, changes no rules and gives no cash reward. Build through the real economy. Completed stages stay on this record when conditions later worsen; the final stage needs a sustained healthy town.</p>${d?d.steps.map((s,i)=>`<div class="mayor-stage ${i<p.stage?'earned':''}"><span>${i<p.stage?(p.completed[i].existingPrerequisite?'EXISTING PREREQUISITE · RECORDED DAY ':'ACHIEVED DAY ')+p.completed[i].day:i===p.stage?'CURRENT':'LATER'}</span><strong>${i+1}. ${esc(s[0])}</strong><p class="desc">${esc(!p.baseline&&['fishery','wharf'].includes(s[2])?'Legacy direction: operate the recorded staffed '+s[2]+'.':s[1])}</p>${i===p.stage?`<b>${mayorStepMet(s[2],m)?p.stage===3?p.held+' / 30 qualifying days':'Conditions met; recorded at next day close':'Conditions still need work'}</b>${mayorExistingWaterfrontAction(s[2])}<button data-mayor-panel="${s[3]}">Work on this stage</button>`:''}</div>`).join(''):''}<details ${d?'':'open'}><summary>${d?'Compare another direction':'Three different ways to grow'}</summary>${Object.entries(TOWN_DIRECTIONS).map(([id,a])=>`<article class="mayor-direction"><h3>${esc(a.title)}</h3><strong>${esc(a.promise)}</strong><p class="desc">${esc(a.tradeoff)}</p><button data-mayor-direction="${id}" ${id===p.direction?'disabled':''}>Review this direction</button></article>`).join('')}</details></section>`;
}
function mayorReviewPanel(){
 const p=mayorJourneyView(),m=mayorMetrics(),r=p.review,labels={employment:'Employment (%)',food:'Food need supplied (%)',hardship:'Household hardship (%)',medical:'Funded medical access (%)',school:'Funded school access (%)',reserve:'Authorized spending reserve (days)'};
 return `<section class="council-card"><h3>Did the decision help?</h3><p class="desc">Save a comparison before a decision, then return after deliveries or staffing have had time to change. This records observations; other events also affect outcomes.</p>${r?`<p class="desc">Day ${r.day} → ${G.day} · ${G.day-r.day} simulated days observed</p><table class="report-table"><thead><tr><th>Observed measure</th><th>Before</th><th>Now</th></tr></thead><tbody>${Object.entries(labels).map(([k,v])=>`<tr><td>${v}</td><td>${fmt(r.metrics[k])}</td><td>${fmt(m[k])}</td></tr>`).join('')}</tbody></table>`:''}<button data-mayor-baseline>${r?'Review replacing comparison':'Record a comparison'}</button></section>`;
}
function mayorFieldNotes(){
 const delivery=G.regionalTrade?.recent?.[0],household=G.households.filter(h=>h.people.length&&readBuild(h.home)).sort((a,b)=>householdLiquidity(a)/a.people.length-householdLiquidity(b)/b.people.length)[0];
 let html='<section class="council-card"><h3>Field notes from the borough</h3><p class="desc">Accounts and observed access, rather than a random opinion poll. These snapshots can change with tomorrow’s settlement.</p>';
 if(delivery){const f=G.firms[delivery.firm];html+=`<article class="mayor-field-note"><strong>A truck reached its destination</strong><p class="desc">Day ${delivery.arrived}: ${fmt(delivery.qty)} ${esc(delivery.good)} ${delivery.direction==='import'?'arrived for':'was delivered by'} ${esc(f?.name||'a local enterprise')}. ${delivery.direction==='import'?'The purchase used enterprise cash before arrival; the goods are now available inventory.':'The outside buyer paid on arrival; receipts belong to the supplying enterprise.'}</p>${f?`<button data-firm="${f.id}">Follow the enterprise account</button>`:''}</article>`;}
 if(household){const h=household;html+=`<article class="mayor-field-note"><strong>A family with the thinnest liquid cushion</strong><p class="desc">The ${esc(h.name)} household has ${h.people.length} residents and ${money(householdLiquidity(h)/h.people.length)} cash and deposits per resident. Recorded daily income ${money(h.income||0)}, food ${money(h.food||0)}, rent ${money(h.rent||0)} and aid ${money(h.aid||0)}. Inspect other expenses before attributing the result to one policy.</p><button data-house="${h.id}">Visit the household account</button></article>`;}
 for(const id of (G.charter?.owned||[]).slice(0,2)){const district=ANNEX_PARCELS.find(a=>a.id===id),m=districtMetrics(id);html+=`<article class="mayor-field-note"><strong>${esc(district.name)} after the deed</strong><p class="desc">${m.pop} residents, ${m.staffed} staffed firms, ${m.connected} connected properties. Observed resident care ${fmt(m.care*100)}%, school access ${fmt(m.school*100)}%. Land ownership alone supplies none of these.</p><button data-district-review="${id}">Visit the district prospectus</button></article>`;}
 return html+'</section>';
}
const mayorOverviewBase=tradingOverviewBase;renderOverviewFull=function(){return mayorDesk()+tradingTownNextDecision()+`<details class="mayor-report"><summary>Full borough report, programme & trading decisions</summary>`+mayorOverviewBase()+'</details>';};
