 const minX=p?p.x:Math.max(2,anchor.x-14),maxX=p?p.x+p.w-1:Math.min(T-3,anchor.x+14),minY=p?p.y:Math.max(2,anchor.y-14),maxY=p?p.y+p.h-1:Math.min(T-3,anchor.y+14);
