function districtHousingContext(parcel){
 const available=typeof migrationHousingStatus==='function'&&typeof migrationAssessment==='function';if(!available)return {available:false,vacancies:0,homes:[]};
 const homes=G.buildings.filter(b=>civicBlueprintInside(parcel,b.x,b.y)&&['home','apartment','tower'].includes(b.kind)).map(b=>({building:b.id,...migrationHousingStatus(b)})),vacancies=homes.reduce((n,h)=>n+(!h.reserved&&!h.underConstruction&&!h.overcrowded?h.available:0),0);return {available:true,vacancies,homes};
}
function districtAdmissionMarkup(plan){if(!plan.housing?.available)return '';const vacant=plan.housing.homes.filter(h=>h.available>0&&!h.reserved&&!h.underConstruction&&!h.overcrowded);return `<div class="civic-watch-line"><b>${plan.housing.vacancies} actual vacant household unit(s) in this tract</b>${vacant.slice(0,6).map(h=>`<button data-district-admission="${h.building}">Assess the vacant address ${h.building}</button>`).join('')}<button data-district-migration-office>Review actual moving decisions</button><details><summary>Why a vacant home does not create residents</summary><p class="desc">New council homes remain municipal rental property. Vacancies do not create residents. Arrival depends on funded reachable work after local jobseekers, household essentials, food access and outside comparisons. Do not buy another home to solve a jobs or affordability problem. The eight-resident goal uses actual settled people. The next housing phase quotes at most one dwelling; reassess actual admission and existing vacancies before funding more. No family size or arrival date is promised.</p></details></div>`;}
function reviewDistrictAdmission(id){if(typeof migrationAssessment!=='function')return;const home=readBuild(id);if(!home)return;const profiles=[{age:30,skill:.45,health:90},{age:30,skill:.45,health:90}],a=migrationAssessment(home,profiles),budget=Object.entries(a.budget||{}).map(([key,n])=>key+': '+mayorUnitMoney(n)+'/day').join('; '),offers=a.offers.map(o=>(G.firms[o.firm]?.name||'former employer')+' '+mayorUnitMoney(o.wage)+'/day, '+o.distance+' road steps, '+mayorUnitMoney(o.fare)+' fare ('+o.mode+')').join('; ');
 showCustomEvent('CIVIC PROJECT',a.eligible?'This sample household could move here':'This sample household cannot move here yet',`Illustrative two adults, age30, skill0.45, health90. These are not actual applicants; no money, jobs, seats or school places are reserved. ${a.eligible?'This example passes current entry conditions; actual family profiles and outside comparisons can still lead to a different choice.':a.reasons.join('; ')} Take-home ${money(a.expectedNet)}/day; essentials ${money(a.essentials)}/day; surplus ${money(a.surplus)}/day. ${budget}. Funded reachable offers: ${offers||'none after local jobseekers'}. Forecast care ${fmt(a.services.health*100)}%, learning ${fmt(a.services.school*100)}%. Outside ${a.outside.name}: reference take-home ${money(a.outside.net)}/day, essentials ${money(a.outside.essentials)}/day. Outside wages/rent are a reference, not a foreign job offer. Any forecast private-school fees are included in essentials without assumed vouchers.`,[{title:'Review funded jobs and enterprise accounts',cost:0,apply:()=>openPanel('businesses')},{title:'Review actual public and private provision',cost:0,apply:()=>openPanel('community')},{title:'Visit this actual address',cost:0,apply:()=>civicProjectVisit(home.x,home.y)}]);
}
function existingDistrictStaffingNote(project,metrics){return metrics.staffed<2?'Inspect existing vacancies and attendance before adding enterprise capital.':'';}
// A complete tract plan is a read-only quote; every purchase remains a separate review.
function districtFollowthroughPlan(project){
 const parcel=ANNEX_PARCELS.find(p=>p.id===project.target),metrics=parcel&&districtMetrics(parcel.id);if(!parcel||project.branch!=='neighbourhood'||!G.charter.owned.includes(parcel.id)||G.districtProgrammes?.[parcel.id]?.focus!=='neighbourhood')return null;
 const housing=districtHousingContext(parcel),needs=[];for(let i=0;i<(housing.available?(housing.vacancies>0||metrics.pop>=8?0:1):Math.ceil(Math.max(0,8-metrics.pop)/2));i++)needs.push('home');if(metrics.pop<8||metrics.care<.4)if(!G.buildings.some(b=>b.kind==='clinic'&&civicBlueprintInside(parcel,b.x,b.y)))needs.push('clinic');if(metrics.pop<8||metrics.school<.4)if(!G.buildings.some(b=>b.kind==='school'&&civicBlueprintInside(parcel,b.x,b.y)))needs.push('school');
 const existing=G.firms.filter(f=>!f.closed&&(()=>{const b=readBuild(f.building);return b&&civicBlueprintInside(parcel,b.x,b.y);})()),neededBusinesses=Math.max(0,2-existing.length),purpose=neededBusinesses?civicDistrictBlueprint(project):{ok:true,roads:[],sites:[],cost:0};if(!purpose.ok)return {parcel:parcel.id,metrics,housing,sites:[],missing:['grocer','bakery'],roadCost:null,cost:0};const businesses=purpose.ok?purpose.sites.filter(s=>!s.existing).slice(0,neededBusinesses).map(s=>({kind:s.kind,x:s.x,y:s.y,cells:s.footprint,cost:buildCost[s.kind],business:true})):[],blocked=new Set(purpose.ok?[...purpose.roads,...purpose.sites.flatMap(s=>s.footprint)]:[]),sites=businesses,missing=[];for(const kind of needs){const candidates=[];for(let y=parcel.y;y<parcel.y+parcel.h;y++)for(let x=parcel.x;x<parcel.x+parcel.w;x++){if(!canPlace(x,y,true,kind))continue;const cells=footprintFor(x,y,kind);if(cells.some(id=>blocked.has(id)||!civicBlueprintInside(parcel,id%T,id/T|0)))continue;candidates.push({kind,x,y,cells,cost:buildCost[kind],distance:Math.abs(x-parcel.x-parcel.w/2)+Math.abs(y-parcel.y-parcel.h/2)});}candidates.sort((a,b)=>a.distance-b.distance||a.y-b.y||a.x-b.x);const site=candidates[0];if(!site){missing.push(kind);continue;}for(const id of site.cells)blocked.add(id);sites.push(site);}
 return {parcel:parcel.id,metrics,housing,sites,missing,roadCost:purpose.ok?purpose.cost:null,cost:sites.reduce((n,s)=>n+s.cost,0)+(purpose.ok?purpose.cost:0)};
}
function districtFollowthroughMarkup(project){const plan=districtFollowthroughPlan(project);if(!plan||project.status!=='active')return '';return `<section class="civic-watch-line"><strong>Finish this actual neighbourhood</strong><p class="desc">Inside ${esc(ANNEX_PARCELS.find(p=>p.id===plan.parcel).name)}: ${plan.metrics.pop}/8 residents, ${plan.metrics.staffed}/2 attending workplaces, care ${fmt(plan.metrics.care*100)}%/40%, teaching ${fmt(plan.metrics.school*100)}%/40%. Town-wide population and coverage do not supply this tract. ${existingDistrictStaffingNote(project,plan.metrics)}</p>${districtAdmissionMarkup(plan)}${plan.sites.length?`<b>Surveyed capital envelope: ${money(plan.cost)}</b><p class="desc">Cash ${money(G.treasury)}. Review one site at a time; no batch purchase.</p><div class="btnrow">${plan.sites.map((s,i)=>`<button data-district-finish="${i}">Review ${esc(types[s.kind].n)} · (${s.x}, ${s.y}) · ${money(s.cost)}</button>`).join('')}</div><details><summary>What this capital envelope includes</summary><p class="desc">${plan.sites.filter(s=>s.kind==='home').length} normal homes, missing business sites, and candidate clinic/school sites listed below. Required streets are reviewed separately before business construction. Purpose street connection ${plan.roadCost==null?'needs a new legal survey':money(plan.roadCost)}; review it through the existing purpose blueprint. Business prices are gross; normal regional permit receipts affect net municipal cash. Build homes first and reassess actual access: existing reachable facilities or private purchases may make the service sites unnecessary. This envelope is not a compulsory shopping list. ${plan.housing.available?'Council-built dwellings are municipal rentals and may remain vacant until actual admission conditions are met.':'This build retains its existing home-settlement rules; causal admission diagnostics require the migration integration.'} Reserved replacement housing instead preserves displaced households. Buildings require reachable staff, operating funds and actual occupancy. No purchase is automatic and no coverage is guaranteed. Current municipal cash ${money(G.treasury)}.</p></details>`:'<p class="desc">No additional legal capital site is identified. Inspect current staffing, access and actual provision before buying another building.</p>'}${plan.missing.length?`<p class="desc">No legal connected footprint for ${esc(plan.missing.join(', '))}. Extend actual streets or review compensated land assembly; this quote excludes unavailable sites and future roads.</p>`:''}<div class="btnrow"><button data-district-service-review>Inspect actual staffing and provision</button><button data-district-budget="educationBudget">Review teaching authorization</button><button data-district-budget="healthBudget">Review care authorization</button><button data-public-assembly>Review compensated sites</button></div><details><summary>All surveyed footprints · no purchase</summary>${plan.sites.map(s=>`<p>${esc(types[s.kind].n)} · ${s.cells.length} tile(s) at (${s.x}, ${s.y})</p>`+civicProjectPlanSvg(s.cells,s)).join('')}</details></section>`;}
function reviewDistrictFinish(index){const project=G.civicProjects?.active.district,plan=project&&districtFollowthroughPlan(project),site=plan?.sites[index];if(!site)return;if(site.business){civicProjectReviewBuild(site.kind,'district');return;}const town=G,pid=project.id,quote=JSON.stringify(plan.sites.map(s=>[s.kind,s.x,s.y,s.cost]));showCustomEvent('CIVIC PROJECT','One neighbourhood purchase: '+types[site.kind].n,`Exact site (${site.x}, ${site.y}), ${site.cells.length} tile(s), ${money(site.cost)}. Cash after this purchase ${money(G.treasury-site.cost)}. Surveyed capital envelope before this purchase ${money(plan.cost)}. The companion sites are advice, not reservations. Operating budgets, access and qualified staff remain separate decisions. ${plan.housing.available&&site.kind==='home'?'This buys a municipal rental dwelling, not a household. No resident is forced to arrive.':''} No other site is charged.`,[{title:'Commission only this reviewed site',cost:0,apply:()=>{const current=G.civicProjects?.active.district,next=current&&districtFollowthroughPlan(current);if(G!==town||current?.id!==pid||current.status!=='active'||!next||JSON.stringify(next.sites.map(s=>[s.kind,s.x,s.y,s.cost]))!==quote||!canPlace(site.x,site.y,true,site.kind)||G.treasury<site.cost){toast('The tract, site plan or funds changed. Review current needs again.');return;}construct(site.kind,site.x,site.y);openCivicProjects('district');}},{title:'Visit this exact site first',cost:0,apply:()=>civicProjectVisit(site.x,site.y)}]);$('eventText').insertAdjacentHTML('afterend','<div class="civic-project-survey">'+civicProjectPlanSvg(site.cells,site)+'</div>');}
const districtFinishCardBase=civicProjectCard;civicProjectCard=function(project){const html=districtFinishCardBase(project),plan=districtFollowthroughMarkup(project);return plan?html.replace('<div class="btnrow">',plan+'<div class="btnrow">'):html;};
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||!G)return;if(b.dataset.districtAdmission)reviewDistrictAdmission(+b.dataset.districtAdmission);if(b.hasAttribute('data-district-migration-office')){openPanel('community');const office=$('migrationOffice');if(office){office.open=true;office.scrollIntoView({block:'start'});}}if(b.dataset.districtFinish!=null)reviewDistrictFinish(+b.dataset.districtFinish);if(['educationBudget','healthBudget'].includes(b.dataset.districtBudget)){openPanel('policies');const input=document.querySelector('[data-policy="'+b.dataset.districtBudget+'"]');if(input){input.closest('details').open=true;input.scrollIntoView({block:'center'});input.focus();}}if(b.hasAttribute('data-district-service-review')){openPanel('community');}});

