// A named place is a real property and its observed surroundings, never an identity bonus.
function publicPlaceState(){return G.publicPlaces||{version:1,places:[]};}
function publicPlaceMetrics(x,y){const near=b=>Math.abs(b.x-x)+Math.abs(b.y-y)<=8,companies=G.firms.filter(f=>{const b=readBuild(f.building);return b&&near(b)&&!f.closed;}),homes=G.households.filter(h=>{const b=readBuild(h.home);return b&&near(b)&&h.people.length;});return {day:G.day,residents:homes.reduce((n,h)=>n+h.people.length,0),retailers:companies.filter(f=>['grocer','bakery','tavern'].includes(f.kind)).length,staff:companies.reduce((n,f)=>n+workingStaff(f).length,0),sales:companies.reduce((n,f)=>n+(f.sales||0),0),handling:companies.filter(f=>f.kind==='warehouse').reduce((n,f)=>n+workingStaff(f).length*120,0),school:homes.length?homes.reduce((n,h)=>n+civicLearnerAccess(h).coverage,0)/homes.length*100:0};}
function publicPlaceOffer(){if(publicPlaceState().places.length>=24)return null;const blocks=Object.values(urbanSpatial().blocks).filter(b=>b.retail&&b.residents>=4).sort((a,b)=>b.retail-a.retail||b.residents-a.residents);for(const block of blocks){if(publicPlaceState().places.some(p=>urbanBlockKey(p.x,p.y)===block.key))continue;const anchor=G.buildings.find(b=>block.buildings.includes(b.id)&&['grocer','bakery','tavern'].includes(b.kind));if(!anchor)continue;const lot=civicProjectLot('warehouse',anchor);if(lot&&canPlace(lot.x,lot.y,true,'square'))return {anchor:anchor.id,x:lot.x,y:lot.y,block:block.key};}return null;}
function publicPlaceReview(kind){const offer=publicPlaceOffer();if(!offer){toast('No shared legally vacant square/warehouse site is currently available beside a populated market. Inspect existing property for compensated assembly.');return;}const town=G,baseline=publicPlaceMetrics(offer.x,offer.y),cost=buildCost[kind],permit=kind==='warehouse'?G.policy.permitFee:0;let chosenName=kind==='square'?'Market Commons':'Market Loading Court';showCustomEvent('CIVIC PROJECT',kind==='square'?'Give the market a public square':'Keep this market plot working',`${baseline.residents} residents, ${baseline.retailers} retailers and ${baseline.staff} attending business workers are within eight grid steps. This actual site can support a market square (${money(buildCost.square)}) or warehouse (${money(buildCost.warehouse)}). A square reserves public space instead of private handling premises. A warehouse needs paid attending crews and real freight. Neither option guarantees more customers, teaching, jobs or happiness. Site purchase now ${money(cost)}; cash afterwards ${money(G.treasury-cost+permit)} after ${money(permit)} existing regional permit receipts. Warehouse startup cash comes from the normal regional investment account. Review the full footprint before committing.`,[{title:'Commission and name this actual place',cost:0,apply:()=>{const name=chosenName.trim();if(!name||name.length>48){toast('Choose a name of 1–48 characters.');return;}if(G!==town||!canPlace(offer.x,offer.y,true,kind)||G.treasury<cost){toast('The site or funds changed; review another quote.');return;}const before=G.nextId;construct(kind,offer.x,offer.y);const b=G.buildings.find(b=>b.id>=before&&b.kind===kind&&b.x===offer.x&&b.y===offer.y);if(!b)return;const state=G.publicPlaces||(G.publicPlaces=publicPlaceState());state.places.push({building:b.id,x:b.x,y:b.y,name,kind,started:G.day,baseline});save();openCivicProjects();}},{title:'Visit the site before deciding',cost:0,apply:()=>civicProjectVisit(offer.x,offer.y)}]);$('eventText').insertAdjacentHTML('afterend',`<div class="civic-project-survey"><label>Place name <input id="publicPlaceName" maxlength="48" value="${kind==='square'?'Market Commons':'Market Loading Court'}"></label>${civicProjectPlanSvg(footprintFor(offer.x,offer.y,kind),offer)}</div>`);$('publicPlaceName').oninput=e=>{chosenName=e.target.value;};}
function publicPlacesPanel(){const state=publicPlaceState();return `<section class="council-card" id="publicLife"><h3>Give the market a future</h3><div class="btnrow"><button data-public-place="square">Review a public market square · ${money(buildCost.square)}</button><button data-public-place="warehouse">Review a working loading court · ${money(buildCost.warehouse)}</button></div><details><summary>The land choice and its consequences</summary><p class="desc">Both reviews seek the same legally buildable market site. Public space uses land and municipal capital; private handling uses more capital and requires payroll and actual traffic. Neither grants an identity bonus. Existing owners remain protected. If no vacant site fits, use the compensated planning office.</p><button data-public-assembly>Review land assembly and replacement housing</button></details>${state.places.map(p=>{const m=publicPlaceMetrics(p.x,p.y),b=readBuild(p.building),present=b&&b.kind===p.kind;return `<article class="entry"><h3>${esc(p.name)}</h3><b>${present?types[p.kind].n:'Former '+types[p.kind].n} · established day ${p.started} · grid ${p.x}, ${p.y}</b><p class="desc">Observed neighbourhood, day ${p.baseline.day} → ${m.day}: residents ${p.baseline.residents} → ${m.residents}; live retailers ${p.baseline.retailers} → ${m.retailers}; attending business workers ${p.baseline.staff} → ${m.staff}; staffed handling ${p.baseline.handling} → ${m.handling} units/day; estimated household learner access ${fmt(p.baseline.school)}% → ${fmt(m.school)}%. ${present?'The named property remains.':'The original property is gone; its dated place record remains.'} Other decisions and events also affect these observations.</p><button data-public-visit="${p.building}">Visit ${esc(p.name)}</button>${present?`<button data-inspect="${p.building}">Inspect the actual property</button>`:''}</article>`;}).join('')}</section>`;}
const publicLifeProjectsBase=civicProjectsPanel;civicProjectsPanel=function(){return publicPlacesPanel()+publicLifeProjectsBase();};
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||!G)return;if(['square','warehouse'].includes(b.dataset.publicPlace))publicPlaceReview(b.dataset.publicPlace);if(b.dataset.publicVisit){const p=publicPlaceState().places.find(p=>p.building===+b.dataset.publicVisit);if(p)civicProjectVisit(p.x,p.y);}if(b.hasAttribute('data-public-assembly')){openPanel('construction');const office=$('urbanPlanningOffice');if(office){office.open=true;office.scrollIntoView({block:'start'});}}});
function validatePublicPlaces(data){const state=data.publicPlaces;if(state==null)return true;if(state.version!==1||!Array.isArray(state.places)||state.places.length>24)return false;const seen=new Set();return state.places.every(p=>{if(!p||!Number.isInteger(p.building)||p.building<1||seen.has(p.building)||typeof p.name!=='string'||!p.name.trim()||p.name.length>48||!['square','warehouse'].includes(p.kind)||!Number.isInteger(p.x)||!Number.isInteger(p.y)||p.x<0||p.y<0||p.x>=T||p.y>=T||!Number.isInteger(p.started)||p.started<1||p.started>data.day||!p.baseline||p.baseline.day!==p.started||!['day','residents','retailers','staff','sales','handling','school'].every(k=>Number.isFinite(p.baseline[k])&&p.baseline[k]>=0&&p.baseline[k]<=1e15))return false;seen.add(p.building);return true;});}
// Stable read-only renderer contract: actual world coordinates, title and continued presence.
function publicPlaceCues(){return publicPlaceState().places.map(p=>({building:p.building,x:p.x,y:p.y,name:p.name,kind:p.kind,present:readBuild(p.building)?.kind===p.kind}));}
const publicLifeOpenBase=openCivicProjects;openCivicProjects=function(kind=''){publicLifeOpenBase(kind);if(!kind)$('publicLife')?.scrollIntoView({block:'start'});};

