   if(progress>.68){slab(g,-w*.42,-d*.37,w*.84,d*.74,h,'#b6a281');for(let j=0;j<3;j++)segment(g,point(-w*.35+j*w*.3,-d*.3,h+1),point(-w*.35+j*w*.3,d*.3,h+1),'#8a7c5c');}
