 for(let j=0;j<4;j++){const q=point(-w*.28+j*w*.14,-d*.04,2);polygon(g,[[q[0]-3,q[1]],[q[0]-1,q[1]-5],[q[0]+4,q[1]-3],[q[0]+5,q[1]+1]],j%2?'#b9b398':'#8f9a84');}
