 for(const x of [-w*.30,w*.30]){slab(g,x-.12,d*.38,.24,.09,4,'#a68c62');for(const leg of [-.09,.09])segment(g,point(x+leg,d*.42,0),point(x+leg,d*.42,4),'#60765f');}
