// SOURCE: 98zzzzzzzzzz-civic-calendar.js
// Voluntary local gatherings: preparation is paid, attendance is informational.
// Renderer API civicGatheringCues(): {id,venue,x,y,name,start,end,capacity,attendance,status}.
let civicCalendarExpanded=false;
function civicCalendarView(){return G.civicCalendar||{version:1,next:1,events:[]};}
function civicGatheringVenues(){return G.buildings.filter(b=>b.kind==='square'&&(b.owner===-1||b.title?.kind==='municipal')).map(b=>({b,name:G.publicPlaces?.places.find(p=>p.building===b.id)?.name||'Square at '+b.x+', '+b.y}));}
function civicGatheringCapacity(b){return b?.kind==='square'?Math.min(72,footprintOf(b).length*24):0;}
function civicGatheringLocalPeople(b){
 const net=graph(),port=net.portals.get(b.id);if(port==null||net.parts[port]!==net.mainPart)return [];const people=[];
 for(const h of G.households){const homePort=net.portals.get(h.home);if(!h.people.length||homePort==null||net.parts[homePort]!==net.mainPart||roadDistance(homePort,port)>12||!(h.food>0)||(h.stress||0)>65)continue;for(const id of h.people){const p=G.people[id];if(p&&!p.deceased&&!p.movedAway&&p.age>=12&&p.health>=60&&!p.commuteBlocked&&!p.publicWork)people.push(id);}}
 return people;
}
function civicGatheringStamp(){return JSON.stringify([G.day,civicCalendarView().next,civicCalendarView().events.map(e=>[e.id,e.status,e.start,e.end])]);}
function reviewCivicGathering(spec){
 const venue=civicGatheringVenues().find(v=>v.b.id===spec?.venue),start=Number(spec?.start),state=civicCalendarView();if(!venue||!Number.isInteger(start)||start<=G.day||start>G.day+30)return {ok:false,reason:'Choose an actual municipal square and a date in the next thirty days.'};
 const port=graph().portals.get(venue.b.id);if(port==null||graph().parts[port]!==graph().mainPart)return {ok:false,reason:'The square has no connected street access. Restore its actual connection before preparation.'};const end=start+1;if(state.events.some(e=>['scheduled','active'].includes(e.status)&&start<=e.end&&end>=e.start))return {ok:false,code:'overlap',reason:'Another gathering already uses these evenings. Choose a separate date.'};if(state.events.length>=16&&!state.events.some(e=>!['scheduled','active'].includes(e.status)))return {ok:false,reason:'The civic calendar is full.'};
 const capacity=civicGatheringCapacity(venue.b),eligible=civicGatheringLocalPeople(venue.b).length,cost=180+capacity*2;return {ok:true,town:G,stamp:civicGatheringStamp(),serial:state.next,venue:venue.b.id,name:venue.name,start,end,capacity,eligible,cost,x:venue.b.x,y:venue.b.y};
}
function authorizeCivicGathering(quote){
 if(!quote?.ok)return {ok:false,reason:quote?.reason||'Review a valid venue and date.'};if(quote.town!==G||quote.stamp!==civicGatheringStamp())return {ok:false,reason:'The calendar changed; review it again.'};const fresh=reviewCivicGathering(quote);if(!fresh.ok||fresh.serial!==quote.serial||fresh.capacity!==quote.capacity||fresh.cost!==quote.cost||fresh.name!==quote.name||fresh.x!==quote.x||fresh.y!==quote.y||fresh.eligible!==quote.eligible)return {ok:false,reason:'Venue, access or participation forecast changed; review again.'};
 if(!Number.isFinite(quote.cost)||quote.cost<0||G.treasury<quote.cost)return {ok:false,reason:'Preparation is not funded. No gathering or payment was created.'};
 const state=G.civicCalendar||(G.civicCalendar=civicCalendarView());if(state.events.length>=16)state.events.splice(state.events.findIndex(e=>!['scheduled','active'].includes(e.status)),1);
 const event={id:state.next++,venue:quote.venue,name:quote.name,x:quote.x,y:quote.y,start:quote.start,end:quote.end,capacity:quote.capacity,cost:quote.cost,paid:quote.cost,created:G.day,lastDay:G.day,status:'scheduled',visits:0,participants:[],daily:[],reason:''};
 G.treasury-=quote.cost;G.region+=quote.cost;G.cumulative.spending+=quote.cost;state.events.push(event);story('Preparation paid for '+event.name+' market neighbours gathering, days '+event.start+'–'+event.end+'. Local leisure only; no sales or outside money are promised.','neutral',event.venue);save();dirty=true;return {ok:true,id:event.id};
}
function cancelCivicGathering(id){const e=G.civicCalendar?.events.find(e=>e.id===id);if(!e||!['scheduled','active'].includes(e.status))return false;e.status='cancelled';e.reason='Cancelled by the mayor. Spent preparation is not refundable.';story(e.name+' gathering cancelled; preparation remains spent.','neutral',e.venue);save();dirty=true;return true;}
function civicGatheringDay(){
 for(const e of G.civicCalendar?.events||[]){if(!['scheduled','active'].includes(e.status)||e.lastDay===G.day)continue;e.lastDay=G.day;if(G.day<e.start)continue;if(G.day>e.end){e.status='complete';story(e.name+' gathering ended: '+e.visits+' modelled local visits, '+e.participants.length+' distinct residents. No extra purchases or income were booked.','neutral',e.venue);continue;}
  const b=readBuild(e.venue),port=b&&graph().portals.get(b.id);if(!b||b.kind!=='square'||port==null||graph().parts[port]!==graph().mainPart||civicGatheringCapacity(b)!==e.capacity){e.status='failed';e.reason='Venue or street access became unavailable; preparation was already spent.';continue;}
  e.status='active';const eligible=civicGatheringLocalPeople(b),attending=eligible.slice().sort((a,b)=>hash(a+e.id*37+G.day*29)-hash(b+e.id*37+G.day*29)).filter(id=>(hash(id+e.id*997+G.day*17)%100)<65).slice(0,e.capacity);e.daily.push({day:G.day,eligible:eligible.length,attendance:attending.length});e.visits+=attending.length;e.participants=[...new Set([...e.participants,...attending])];
 }
}
// Canonical end-of-day callback; no cooperative-simulation barrier is replaced.
const gatheringCampaignDayBase=civicCampaignDay;civicCampaignDay=function(){gatheringCampaignDayBase();civicGatheringDay();};
function civicGatheringCues(){return (G?.civicCalendar?.events||[]).filter(e=>e.status==='active'&&G.day>=e.start&&G.day<=e.end&&readBuild(e.venue)?.kind==='square').map(e=>({id:e.id,venue:e.venue,x:e.x,y:e.y,name:e.name,start:e.start,end:e.end,capacity:e.capacity,attendance:fromEnd(e.daily)?.attendance||0,status:e.status}));}
function openCivicGatheringReview(venue){const spec={venue,start:G.day+1};let quote=reviewCivicGathering(spec);for(let start=G.day+2;!quote.ok&&quote.code==='overlap'&&start<=G.day+30;start++)quote=reviewCivicGathering({venue,start});if(!quote.ok){toast(quote.reason);return;}const loading=reviewMarketLoadingChoice();showCustomEvent('CIVIC PROJECT','Prepare a market neighbours gathering',`${quote.name}: two after-shift evenings, ${quote.capacity} modelled places per evening. Preparation ${money(quote.cost)} goes to regional suppliers now; it cannot be refunded after cancellation. Municipal cash ${money(G.treasury)} → ${money(G.treasury-quote.cost)}; preparation competes with actual service funding. Current walking-distance residents meeting food/health/leisure conditions: ${quote.eligible}. A date is not an attendance guarantee. No admission fee, vendor sale, outside visitor money, happiness or education bonus is added. Shops continue their ordinary trading. Attendance is an aggregate local leisure model: no extra jobs, trips or transit seats are booked.`,[{title:'Pay preparation and place on the calendar',cost:0,apply:()=>{const result=authorizeCivicGathering(quote);toast(result.ok?'Gathering prepared. Visit the active square and pause to enjoy it.':result.reason);openCivicProjects();}},...(loading.ok?[{title:'Instead: prioritize essentials and authorize paid extra shifts',cost:0,apply:()=>{const r=authorizeMarketLoadingChoice(loading);toast(r.reason);openCivicProjects();}},{title:'Instead: essentials first using existing crews',cost:0,apply:()=>{const r=authorizeMarketLoadingChoice(loading,false);toast(r.reason);openCivicProjects();}}]:[])]);$('eventText').insertAdjacentHTML('afterend',`<div class="civic-project-survey"><p class="desc">${esc(loading.summary)}</p><label>Opening simulated day <input id="gatheringStart" type="number" min="${G.day+1}" max="${G.day+30}" value="${quote.start}"></label><p class="desc">Choose another date before payment. Only one gathering may use a given evening. Local walking catchment: twelve road steps; public-duty/callout staff, blocked commuters and unfed households are excluded. Participation assumptions are disclosed, not a claim of tracked individual leisure trips.</p></div>`);$('gatheringStart').oninput=e=>{quote=reviewCivicGathering({venue,start:Number(e.target.value)});};}
function civicCalendarPanel(){const state=civicCalendarView(),venues=civicGatheringVenues();return `<details class="council-card" id="civicCalendar" ${civicCalendarExpanded?'open':''}><summary>Civic calendar · ${state.events.filter(e=>['scheduled','active'].includes(e.status)).length} upcoming / active</summary><p class="desc">Make an actual square a place to meet. Preparation competes with public services and capital; there is no free-money reward. Gathering crowds are bounded visual samples, not extra economic agents.</p>${venues.length?venues.slice(0,12).map(v=>`<button data-gathering-review="${v.b.id}">Prepare ${esc(v.name)} · ${money(180+civicGatheringCapacity(v.b)*2)}</button>`).join(''):'<p class="desc">No municipal square is available. Review a real public market square above before planning a gathering.</p>'}${state.events.slice().reverse().map(e=>`<article class="entry"><strong>${esc(e.name)} · days ${e.start}–${e.end}</strong><p class="desc">${esc(e.status)} · preparation paid ${money(e.paid)} · ${e.visits} modelled visits / ${e.participants.length} distinct local residents. Capacity ${e.capacity} per evening. ${esc(e.reason)} ${readBuild(e.venue)?.kind==='square'?'':'The original venue is gone; this is a paid historical record, not an available gathering site.'}</p><button data-gathering-visit="${e.id}">${readBuild(e.venue)?.kind!=='square'?'Visit the recorded site':e.status==='active'?'Visit the active gathering and pause':'Visit the real square'}</button>${['scheduled','active'].includes(e.status)?`<button data-gathering-cancel="${e.id}">Review cancellation</button>`:''}</article>`).join('')}</details>`;}
const gatheringPublicPanelBase=publicPlacesPanel;publicPlacesPanel=function(){return gatheringPublicPanelBase()+civicCalendarPanel();};
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||!G)return;if(b.dataset.gatheringReview)openCivicGatheringReview(+b.dataset.gatheringReview);if(b.dataset.gatheringCancel){const id=+b.dataset.gatheringCancel;showCustomEvent('CIVIC PROJECT','Cancel this gathering?','Preparation is already paid and is not refunded. Ordinary shops, wages and services continue.',[{title:'Cancel the remaining gathering',cost:0,apply:()=>{cancelCivicGathering(id);openCivicProjects();}}]);}if(b.dataset.gatheringVisit){const event=G.civicCalendar?.events.find(a=>a.id===+b.dataset.gatheringVisit);if(event){if(event.status==='active'&&!paused)$('pause').click();civicProjectVisit(event.x,event.y);}}});
function validateCivicCalendar(data){const s=data.civicCalendar;if(s==null)return true;if(s.version!==1||!Number.isSafeInteger(s.next)||s.next<1||s.next>1e9||!Array.isArray(s.events)||s.events.length>16)return false;const ids=new Set();return s.events.every(e=>{if(!e||!Number.isSafeInteger(e.id)||e.id<1||e.id>=s.next||ids.has(e.id)||!Number.isInteger(e.venue)||e.venue<1||typeof e.name!=='string'||e.name.length>100||!Number.isInteger(e.x)||!Number.isInteger(e.y)||e.x<0||e.y<0||e.x>=T||e.y>=T||!Number.isInteger(e.created)||e.created<1||e.created>data.day||!Number.isInteger(e.start)||e.start<=e.created||e.start>data.day+30||e.end!==e.start+1||!Number.isInteger(e.lastDay)||e.lastDay<e.created||e.lastDay>data.day||!['scheduled','active','complete','cancelled','failed'].includes(e.status)||!Number.isInteger(e.capacity)||e.capacity<1||e.capacity>72||!Number.isFinite(e.cost)||e.cost<0||e.cost>1e6||e.paid!==e.cost||typeof e.reason!=='string'||e.reason.length>400||!Array.isArray(e.daily)||e.daily.length>2||!Array.isArray(e.participants)||e.participants.length>144||new Set(e.participants).size!==e.participants.length||e.participants.some(id=>!Number.isInteger(id)||!data.people[id])||!Number.isInteger(e.visits)||e.visits<0||e.visits>e.capacity*2||e.participants.length>e.visits||e.daily.some((d,i)=>!Number.isInteger(d.day)||d.day<e.start||d.day>e.end||d.day>data.day||i&&d.day<=e.daily[i-1].day||!Number.isInteger(d.eligible)||d.eligible<0||d.eligible>data.people.length||!Number.isInteger(d.attendance)||d.attendance<0||d.attendance>e.capacity||d.attendance>d.eligible)||e.visits!==e.daily.reduce((n,d)=>n+d.attendance,0))return false;ids.add(e.id);return true;})&&s.events.filter(e=>['scheduled','active'].includes(e.status)).every((e,i,a)=>a.slice(i+1).every(other=>e.end<other.start||e.start>other.end));}
const gatheringPlaceValidatorBase=validatePublicPlaces;validatePublicPlaces=function(data){return gatheringPlaceValidatorBase(data)&&validateCivicCalendar(data);};
