function paintCivicGathering(g,item,cue){g.save();g.translate(item.x,item.y);g.strokeStyle='#5e6548';g.lineWidth=1.5;g.beginPath();g.moveTo(-22,-15);g.lineTo(-22,-38);g.moveTo(22,-15);g.lineTo(22,-38);g.stroke();const phase=gameOptions.reducedMotion||!gameOptions.effects?0:(G.day+acc/1.65)*6;g.beginPath();g.moveTo(-22,-35);g.quadraticCurveTo(0,-28+Math.sin(phase),22,-35);g.stroke();for(let i=0;i<6;i++){const x=-19+i*7;g.fillStyle=i%2?'#b26c55':'#e0c263';g.beginPath();g.moveTo(x,-33);g.lineTo(x+5,-33);g.lineTo(x+3,-26);g.fill();}if(cam.zoom>=.55&&gameOptions.effects&&gameOptions.traffic){const n=Math.min(cue.attendance,fastRenderEnabled()?3:8);for(let i=0;i<n;i++){const a=i*2.4,x=Math.cos(a)*14+Math.sin(phase+i)*1.2,y=Math.sin(a)*7-5;g.fillStyle=['#607b72','#ab7655','#887295'][i%3];g.fillRect(x-1.5,y-6,3,5);g.fillStyle='#d2ad82';g.beginPath();g.arc(x,y-8,2,0,Math.PI*2);g.fill();}}g.restore();}
const gatheringSceneBase=drawSceneSprite;drawSceneSprite=function(g,item){gatheringSceneBase(g,item);if(item.kind!=='building'||item.b.kind!=='square'||cam.zoom<.32)return;const cue=civicGatheringCues().find(e=>e.venue===item.b.id);if(cue)paintCivicGathering(g,item,cue);};

